import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-admin-l4-001', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'What is the difference between a physical replication slot and a logical replication slot?', options: ['They are identical', 'Physical replication slots stream raw WAL bytes for full database replication, while logical replication slots decode WAL into logical changes (inserts, updates, deletes) allowing selective table replication across potentially different PostgreSQL versions', 'Logical slots are faster', 'Physical slots support cross-version replication'], correctAnswer: 1, explanation: 'Physical replication slots ensure WAL is retained for streaming replication standbys, transmitting raw WAL bytes. Logical replication slots use output plugins to decode WAL into logical change events, enabling selective replication, cross-version replication, and integration with external systems. Logical slots require wal_level = logical.', codeSnippet: "-- Create a logical replication slot\nSELECT pg_create_logical_replication_slot(\n  'my_slot', 'pgoutput'\n);\n\n-- Create a physical replication slot\nSELECT pg_create_physical_replication_slot('phys_slot');\n\n-- List all replication slots\nSELECT slot_name, slot_type, plugin, active,\n  restart_lsn, confirmed_flush_lsn\nFROM pg_replication_slots;", tags: ['admin', 'logical-replication', 'replication-slots', 'wal'] },
  { id: 'pg-admin-l4-002', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you monitor logical replication lag in PostgreSQL?', options: ['Use pg_stat_activity only', 'Query pg_stat_replication for sent_lsn vs write_lsn/flush_lsn/replay_lsn differences, and on the subscriber check pg_stat_subscription for the latest_end_lsn and last_msg_receipt_time to measure both network and apply lag', 'Check the PostgreSQL log files', 'Lag cannot be monitored'], correctAnswer: 1, explanation: 'On the publisher, pg_stat_replication shows WAL positions (sent, write, flush, replay) for each subscriber. On the subscriber, pg_stat_subscription shows last received LSN and timestamps. The difference between pg_current_wal_lsn() on the publisher and the subscriber latest_end_lsn indicates total lag.', codeSnippet: "-- On publisher: check replication lag\nSELECT pid, application_name, client_addr,\n  state, sync_state,\n  pg_wal_lsn_diff(pg_current_wal_lsn(), sent_lsn) AS send_lag,\n  pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn) AS replay_lag\nFROM pg_stat_replication;\n\n-- On subscriber: check subscription status\nSELECT subname, pid, relid,\n  received_lsn, last_msg_send_time,\n  last_msg_receipt_time, latest_end_lsn\nFROM pg_stat_subscription;", tags: ['admin', 'logical-replication', 'monitoring', 'lag'] },
  { id: 'pg-admin-l4-003', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'What happens when a logical replication slot is not consumed and WAL accumulates?', options: ['WAL is automatically cleaned up', 'Unconsumed logical replication slots prevent WAL segment removal, causing disk usage to grow indefinitely until the slot is either consumed, dropped, or the max_slot_wal_keep_size limit (PG 13+) causes the slot to be invalidated', 'The slot pauses automatically', 'PostgreSQL compresses the WAL'], correctAnswer: 1, explanation: 'Logical replication slots track the WAL position needed by the subscriber. If the subscriber is down or slow, WAL files accumulate without being recycled. In PG 13+, max_slot_wal_keep_size limits this growth by invalidating the slot when the threshold is exceeded. Without this setting, disk can fill completely.', codeSnippet: "-- Set maximum WAL retained per slot (PG 13+)\nALTER SYSTEM SET max_slot_wal_keep_size = '50GB';\nSELECT pg_reload_conf();\n\n-- Monitor slot WAL usage\nSELECT slot_name, slot_type, active,\n  pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)\n    AS retained_bytes,\n  pg_size_pretty(\n    pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)\n  ) AS retained_size\nFROM pg_replication_slots;\n\n-- Drop an unused slot\nSELECT pg_drop_replication_slot('orphaned_slot');", tags: ['admin', 'logical-replication', 'wal', 'disk-usage'] },
  { id: 'pg-admin-l4-004', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you set up logical replication for a subset of tables with row filters?', options: ['Use WHERE in CREATE SUBSCRIPTION', 'In PG 15+, CREATE PUBLICATION supports WHERE clauses to filter rows and column lists to select columns — only matching rows/columns are replicated to subscribers, reducing network and storage overhead', 'Row filtering is not supported', 'Use triggers to filter rows'], correctAnswer: 1, explanation: 'PostgreSQL 15 added row filter support (WHERE clause) and column lists to publications. Only rows matching the WHERE condition and specified columns are sent to subscribers. This is useful for multi-tenant setups, GDPR compliance, or regional data distribution.', codeSnippet: "-- Create publication with row filter (PG 15+)\nCREATE PUBLICATION pub_active_users\n  FOR TABLE users WHERE (active = true),\n  TABLE orders (id, user_id, total, created_at)\n  WHERE (created_at > '2024-01-01');\n\n-- On subscriber:\nCREATE SUBSCRIPTION sub_active_users\n  CONNECTION 'host=pub dbname=mydb user=repl_user'\n  PUBLICATION pub_active_users;\n\n-- Verify publication tables and filters\nSELECT * FROM pg_publication_tables\nWHERE pubname = 'pub_active_users';", tags: ['admin', 'logical-replication', 'row-filter', 'pg15'] },
  { id: 'pg-admin-l4-005', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'What is the role of the pgoutput plugin in logical replication?', options: ['It formats output to CSV', 'pgoutput is the built-in logical decoding output plugin used by native logical replication — it converts WAL changes into a protocol that CREATE SUBSCRIPTION understands, supporting filtering, column lists, and binary format', 'It compresses WAL output', 'It encrypts replication data'], correctAnswer: 1, explanation: 'pgoutput is PostgreSQL native logical decoding output plugin introduced with logical replication in PG 10. It encodes changes into the logical replication protocol consumed by pg_recvlogical or the subscription apply worker. Other plugins like wal2json or test_decoding provide different output formats.', codeSnippet: "-- pgoutput is used automatically by subscriptions\nCREATE PUBLICATION my_pub FOR ALL TABLES;\n\n-- Explicitly create slot with pgoutput\nSELECT pg_create_logical_replication_slot(\n  'my_slot', 'pgoutput'\n);\n\n-- Compare with other plugins:\n-- test_decoding: text format for debugging\nSELECT pg_create_logical_replication_slot(\n  'test_slot', 'test_decoding'\n);\n\n-- Peek at decoded changes\nSELECT * FROM pg_logical_slot_peek_changes(\n  'test_slot', NULL, NULL\n);", tags: ['admin', 'logical-replication', 'pgoutput', 'logical-decoding'] },
  { id: 'pg-admin-l4-006', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you handle schema changes (DDL) with logical replication?', options: ['DDL is automatically replicated', 'Logical replication does NOT replicate DDL — schema changes must be applied manually on the subscriber before or after the publisher change, and the publication/subscription may need adjustment for new tables or altered columns', 'Use ALTER SUBSCRIPTION to replicate DDL', 'DDL changes are ignored safely'], correctAnswer: 1, explanation: 'Unlike physical replication, logical replication only replicates DML (INSERT/UPDATE/DELETE). DDL (CREATE TABLE, ALTER TABLE, etc.) must be manually coordinated. Add columns on subscriber first (nullable), then publisher. For new tables, add to publication and refresh subscription.', codeSnippet: "-- Step 1: Add column on SUBSCRIBER first\nALTER TABLE orders ADD COLUMN region TEXT;\n\n-- Step 2: Add column on PUBLISHER\nALTER TABLE orders ADD COLUMN region TEXT;\n\n-- For new tables:\n-- Publisher:\nCREATE TABLE new_table (...);\nALTER PUBLICATION my_pub ADD TABLE new_table;\n\n-- Subscriber:\nCREATE TABLE new_table (...);  -- same schema\nALTER SUBSCRIPTION my_sub REFRESH PUBLICATION;", tags: ['admin', 'logical-replication', 'ddl', 'schema-changes'] },
  { id: 'pg-admin-l4-007', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'What are logical replication conflicts and how are they resolved?', options: ['Conflicts never occur in logical replication', 'Conflicts occur when a subscriber cannot apply a change (e.g., unique violation, missing row for UPDATE/DELETE) — they cause the apply worker to stop and retry until the conflict is manually resolved by fixing data or skipping the transaction', 'Conflicts are auto-resolved using last-write-wins', 'The publisher retries the operation'], correctAnswer: 1, explanation: 'Logical replication conflicts happen when subscriber data is inconsistent with incoming changes. Common causes: duplicate key on INSERT, missing row for UPDATE/DELETE, or constraint violations. The apply worker retries indefinitely. Resolution requires manual intervention: fix the conflicting data, or use ALTER SUBSCRIPTION ... SKIP to skip the failing transaction (PG 15+).', codeSnippet: "-- Check for replication conflicts in subscriber logs\n-- LOG: logical replication apply worker for subscription\n-- \"my_sub\" has started\n-- ERROR: duplicate key value violates unique constraint\n\n-- Option 1: Fix the conflicting data\nDELETE FROM subscriber_table WHERE id = 42;\n\n-- Option 2: Skip the failing transaction (PG 15+)\nALTER SUBSCRIPTION my_sub\n  SKIP (lsn = '0/12345678');\n\n-- Option 3: Disable and re-sync\nALTER SUBSCRIPTION my_sub DISABLE;\n-- Fix data, then:\nALTER SUBSCRIPTION my_sub ENABLE;", tags: ['admin', 'logical-replication', 'conflicts', 'troubleshooting'] },
  { id: 'pg-admin-l4-008', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'How does pg_basebackup with WAL streaming (-Xs) differ from fetch mode (-Xf)?', options: ['They are identical', 'Fetch mode collects WAL files after the backup completes (risking WAL removal during long backups), while stream mode opens a second connection to stream WAL concurrently during the backup, ensuring all required WAL is captured in real-time', 'Stream mode is slower', 'Fetch mode is more reliable'], correctAnswer: 1, explanation: 'With -Xf (fetch), pg_basebackup retrieves WAL files after backup completes. If the backup takes long and wal_keep_size is insufficient, required WAL may be recycled, causing failure. With -Xs (stream), a second replication connection streams WAL continuously during backup, guaranteeing all WAL is available. -Xs requires max_wal_senders >= 2.', codeSnippet: "-- Stream mode (recommended):\npg_basebackup -h primary -D /backup/data \\\n  -U repl_user -Fp -Xs -P -v\n  -- -Xs: stream WAL via second connection\n  -- -Fp: plain format\n  -- -P: show progress\n\n-- Fetch mode:\npg_basebackup -h primary -D /backup/data \\\n  -U repl_user -Fp -Xf -P\n  -- -Xf: fetch WAL after backup\n\n-- Compressed tar format with streaming:\npg_basebackup -h primary -D /backup/ \\\n  -U repl_user -Ft -Xs -z -P\n  -- -Ft: tar format, -z: gzip compression", tags: ['admin', 'pg-basebackup', 'wal-streaming', 'backup'] },
  { id: 'pg-admin-l4-009', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'How do you use pg_basebackup to create a compressed backup with server-side compression?', options: ['Use -z flag only', 'PostgreSQL 15+ supports --compress=server-gzip:level to perform compression on the server side, reducing network bandwidth; earlier versions support client-side compression (-z/-Z) which compresses after receiving data', 'Compression is not supported', 'Use pg_dump instead'], correctAnswer: 1, explanation: 'Server-side compression (PG 15+) reduces network bandwidth by compressing data before transmission. Client-side compression (-z) reduces disk usage but still transfers uncompressed data over the network. PG 15+ also supports lz4 and zstd compression algorithms with --compress option.', codeSnippet: "-- Server-side gzip compression (PG 15+):\npg_basebackup -h primary -D /backup/ \\\n  -Ft --compress=server-gzip:9 -Xs -P\n\n-- Server-side LZ4 compression (PG 15+):\npg_basebackup -h primary -D /backup/ \\\n  -Ft --compress=server-lz4 -Xs -P\n\n-- Client-side compression (all versions):\npg_basebackup -h primary -D /backup/ \\\n  -Ft -z -Xs -P\n  -- or: -Z 9 for max compression level\n\n-- Server-side zstd (PG 15+):\npg_basebackup -h primary -D /backup/ \\\n  -Ft --compress=server-zstd:3 -Xs -P", tags: ['admin', 'pg-basebackup', 'compression', 'pg15'] },
  { id: 'pg-admin-l4-010', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'What is the --max-rate option in pg_basebackup and when should you use it?', options: ['It sets the maximum query rate', 'It limits the data transfer rate (bytes/second) during backup to reduce I/O and network load on the primary server, preventing backup operations from degrading production workload performance', 'It limits the number of WAL files', 'It controls the replication speed'], correctAnswer: 1, explanation: '--max-rate throttles backup throughput. Useful on production servers where unthrottled backups could saturate disk I/O or network bandwidth. The value is in KB/s (default unlimited). Even a small throttle (e.g., 100MB/s) can prevent backup from starving production queries of I/O bandwidth.', codeSnippet: "-- Limit to 100 MB/s:\npg_basebackup -h primary -D /backup/data \\\n  -U repl_user -Fp -Xs -P \\\n  --max-rate=100M\n\n-- Limit to 50 MB/s:\npg_basebackup -h primary -D /backup/data \\\n  --max-rate=50M -Xs -Ft -z\n\n-- Values: suffix K (KB/s), M (MB/s), or plain (KB/s)\n-- Minimum: 32 KB/s\n-- Default: 0 (unlimited)", tags: ['admin', 'pg-basebackup', 'throttling', 'performance'] },
  { id: 'pg-admin-l4-011', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'How do you verify the integrity of a pg_basebackup backup?', options: ['Simply check the file sizes', 'Use pg_verifybackup (PG 13+) which reads the backup_manifest file to verify all files are present, have correct sizes and checksums, and validates the WAL files needed for recovery are included', 'Run pg_dump on the backup', 'There is no verification tool'], correctAnswer: 1, explanation: 'pg_verifybackup was introduced in PostgreSQL 13. It reads the backup_manifest file (generated by pg_basebackup) containing file paths, sizes, and CRC checksums. It verifies every file matches the manifest and optionally validates WAL coverage. This catches corruption during backup or storage.', codeSnippet: "-- Take a backup (manifest is created automatically)\npg_basebackup -D /backup/data -Fp -Xs -P\n\n-- Verify the backup:\npg_verifybackup /backup/data\n\n-- Verify with WAL validation:\npg_verifybackup -w /backup/data\n  -- -w: also verify WAL files\n\n-- Verify tar format backup:\npg_verifybackup -e ./base.tar /backup/\n\n-- Output on success:\n-- backup successfully verified\n\n-- Output on failure:\n-- pg_verifybackup: error: file \"base/...\" has\n-- checksum mismatch", tags: ['admin', 'pg-basebackup', 'verification', 'backup-integrity'] },
  { id: 'pg-admin-l4-012', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How does the autovacuum_vacuum_scale_factor parameter affect vacuum triggering?', options: ['It sets the vacuum frequency in minutes', 'It defines the fraction of the table that must be dead tuples before autovacuum triggers — the threshold is autovacuum_vacuum_threshold + autovacuum_vacuum_scale_factor * table_size, so larger tables need more dead tuples proportionally', 'It controls the number of vacuum workers', 'It sets the I/O throttle for vacuum'], correctAnswer: 1, explanation: 'The formula is: vacuum when dead_tuples >= threshold + scale_factor * reltuples. Default scale_factor is 0.2 (20%) and threshold is 50. For a 10M row table, this means ~2M dead tuples before vacuum. For very large tables, reduce scale_factor or set per-table overrides to vacuum more frequently.', codeSnippet: "-- Default formula: dead_tuples >= 50 + 0.2 * n_live_tup\n\n-- Global settings:\nALTER SYSTEM SET autovacuum_vacuum_scale_factor = 0.1;\nALTER SYSTEM SET autovacuum_vacuum_threshold = 50;\n\n-- Per-table override for large tables:\nALTER TABLE large_events SET (\n  autovacuum_vacuum_scale_factor = 0.01,\n  autovacuum_vacuum_threshold = 1000\n);\n-- Triggers at: 1000 + 0.01 * n_live_tup dead tuples\n\n-- Check current dead tuple counts:\nSELECT relname, n_live_tup, n_dead_tup,\n  last_autovacuum\nFROM pg_stat_user_tables\nORDER BY n_dead_tup DESC;", tags: ['admin', 'autovacuum', 'scale-factor', 'tuning'] },
  { id: 'pg-admin-l4-013', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'What is autovacuum_vacuum_cost_delay and how does it throttle autovacuum I/O?', options: ['It delays the start of autovacuum', 'It specifies the time (in ms) autovacuum sleeps after accumulating autovacuum_vacuum_cost_limit worth of I/O cost — lower values make vacuum faster but increase I/O impact on production, higher values reduce I/O impact but slow down cleanup', 'It limits the number of pages vacuumed', 'It controls network delay for replication'], correctAnswer: 1, explanation: 'Autovacuum uses the cost-based vacuum delay mechanism. Each page read/write has a cost (vacuum_cost_page_hit=1, miss=2, dirty=20). When accumulated cost reaches cost_limit (default 200), vacuum sleeps for cost_delay ms (default 2ms in PG 12+). Tuning these controls the I/O bandwidth vacuum consumes.', codeSnippet: "-- Make autovacuum more aggressive (faster cleanup):\nALTER SYSTEM SET autovacuum_vacuum_cost_delay = 2;\nALTER SYSTEM SET autovacuum_vacuum_cost_limit = 400;\n\n-- Make autovacuum less aggressive (less I/O impact):\nALTER SYSTEM SET autovacuum_vacuum_cost_delay = 10;\nALTER SYSTEM SET autovacuum_vacuum_cost_limit = 200;\n\n-- Per-table override for critical tables:\nALTER TABLE hot_table SET (\n  autovacuum_vacuum_cost_delay = 0,\n  autovacuum_vacuum_cost_limit = 1000\n);\n\n-- I/O costs: page_hit=1, page_miss=2, page_dirty=20", tags: ['admin', 'autovacuum', 'cost-delay', 'io-throttling'] },
  { id: 'pg-admin-l4-014', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'Why is autovacuum_freeze_max_age critical and what happens when it is reached?', options: ['It controls the maximum age of connections', 'When a table transaction ID age reaches autovacuum_freeze_max_age (default 200M), an aggressive anti-wraparound vacuum is forced that cannot be cancelled — this prevents transaction ID wraparound which would make the database refuse all writes', 'It sets the maximum backup age', 'It limits the replication lag age'], correctAnswer: 1, explanation: 'PostgreSQL uses 32-bit transaction IDs that wraparound at ~4 billion. autovacuum_freeze_max_age triggers forced freezing of old transaction IDs. If the database reaches ~2 billion unfrozen XIDs, it shuts down to prevent wraparound data loss. Monitor with pg_database.datfrozenxid and act before emergency shutdowns.', codeSnippet: "-- Check transaction ID age per database\nSELECT datname,\n  age(datfrozenxid) AS xid_age,\n  2147483647 - age(datfrozenxid) AS remaining_xids\nFROM pg_database\nORDER BY age(datfrozenxid) DESC;\n\n-- Check per-table XID age\nSELECT relname,\n  age(relfrozenxid) AS xid_age,\n  pg_size_pretty(pg_total_relation_size(oid)) AS size\nFROM pg_class\nWHERE relkind = 'r'\nORDER BY age(relfrozenxid) DESC\nLIMIT 20;\n\n-- Tune freezing parameters:\nALTER SYSTEM SET autovacuum_freeze_max_age = 200000000;\nALTER SYSTEM SET vacuum_freeze_min_age = 50000000;", tags: ['admin', 'autovacuum', 'freeze', 'xid-wraparound'] },
  { id: 'pg-admin-l4-015', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How do you tune autovacuum for a table with very high UPDATE rates?', options: ['Disable autovacuum on the table', 'Reduce autovacuum_vacuum_scale_factor and increase autovacuum_vacuum_cost_limit per-table to vacuum more frequently and aggressively, and consider using FILLFACTOR < 100 to enable HOT updates which reduce dead tuple generation', 'Increase shared_buffers instead', 'Switch to UNLOGGED tables'], correctAnswer: 1, explanation: 'High-update tables generate many dead tuples quickly. Lowering scale_factor triggers vacuum sooner. Increasing cost_limit speeds up vacuum. FILLFACTOR < 100 reserves page space for HOT (Heap Only Tuple) updates that avoid index bloat. For very hot tables, consider partitioning to keep individual partitions manageable.', codeSnippet: "-- Aggressive autovacuum for high-update table:\nALTER TABLE hot_table SET (\n  autovacuum_vacuum_scale_factor = 0.02,\n  autovacuum_vacuum_threshold = 100,\n  autovacuum_vacuum_cost_delay = 0,\n  autovacuum_vacuum_cost_limit = 2000,\n  autovacuum_analyze_scale_factor = 0.01,\n  autovacuum_analyze_threshold = 100,\n  fillfactor = 70  -- reserve 30% for HOT updates\n);\n\n-- Monitor HOT update ratio:\nSELECT relname, n_tup_upd, n_tup_hot_upd,\n  CASE WHEN n_tup_upd > 0\n    THEN round(100.0 * n_tup_hot_upd / n_tup_upd, 1)\n    ELSE 0 END AS hot_pct\nFROM pg_stat_user_tables\nWHERE n_tup_upd > 1000\nORDER BY n_tup_upd DESC;", tags: ['admin', 'autovacuum', 'high-update', 'hot-updates', 'fillfactor'] },
  { id: 'pg-admin-l4-016', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How does autovacuum_max_workers interact with autovacuum_vacuum_cost_limit?', options: ['Each worker gets the full cost_limit', 'The global autovacuum_vacuum_cost_limit is shared across all active autovacuum workers — if cost_limit is 200 and there are 4 workers, each gets only 50, making individual vacuums slower; increase cost_limit proportionally to the number of workers', 'Workers run sequentially with full cost_limit', 'cost_limit only applies to manual VACUUM'], correctAnswer: 1, explanation: 'The cost_limit is divided equally among active workers. With default cost_limit=200 and 3 workers, each gets ~67. If you increase max_workers, also increase cost_limit to maintain per-worker throughput. Alternatively, set per-table cost_limit which is not shared. PG 12+ uses cost_delay=2ms (was 20ms).', codeSnippet: "-- 5 workers, each needs reasonable throughput:\nALTER SYSTEM SET autovacuum_max_workers = 5;\nALTER SYSTEM SET autovacuum_vacuum_cost_limit = 1000;\n-- Each worker gets 200 (1000/5)\n\n-- Per-table cost_limit is NOT shared:\nALTER TABLE critical_table SET (\n  autovacuum_vacuum_cost_limit = 500\n  -- This table's worker gets full 500\n);\n\n-- Monitor active autovacuum workers:\nSELECT pid, query, state,\n  now() - xact_start AS duration\nFROM pg_stat_activity\nWHERE query LIKE 'autovacuum:%';", tags: ['admin', 'autovacuum', 'max-workers', 'cost-limit'] },
  { id: 'pg-admin-l4-017', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'What is the autovacuum_analyze_scale_factor and why should you tune it separately from vacuum?', options: ['It controls VACUUM FULL frequency', 'It determines when autoanalyze runs — the threshold is autovacuum_analyze_threshold + scale_factor * table_size — tuning it ensures statistics stay current for the query planner, which may need more frequent updates than dead tuple cleanup', 'It sets the sample size for ANALYZE', 'It controls index statistics collection'], correctAnswer: 1, explanation: 'ANALYZE updates table statistics used by the query planner. The formula mirrors vacuum: changed_tuples >= threshold + scale_factor * reltuples. Default is 0.1 (10%). For tables with changing data distribution, lower this to keep statistics fresh. Stale statistics cause poor query plans, which may be worse than some dead tuples.', codeSnippet: "-- More frequent ANALYZE for tables with changing distribution:\nALTER TABLE search_logs SET (\n  autovacuum_analyze_scale_factor = 0.02,\n  autovacuum_analyze_threshold = 500\n);\n\n-- Check when tables were last analyzed:\nSELECT relname, n_live_tup, n_mod_since_analyze,\n  last_autoanalyze,\n  CASE WHEN n_live_tup > 0\n    THEN round(100.0 * n_mod_since_analyze / n_live_tup, 1)\n    ELSE 0 END AS pct_modified\nFROM pg_stat_user_tables\nORDER BY n_mod_since_analyze DESC;", tags: ['admin', 'autovacuum', 'analyze', 'statistics'] },
  { id: 'pg-admin-l4-018', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Huge Pages', question: 'What are huge pages in PostgreSQL and why are they beneficial?', options: ['Pages that store large objects', 'Huge pages are OS-level memory pages (typically 2MB instead of 4KB) that reduce Translation Lookaside Buffer (TLB) misses and page table overhead when PostgreSQL uses large shared_buffers, significantly improving memory-intensive workload performance', 'They increase the maximum table size', 'They allow larger WAL segments'], correctAnswer: 1, explanation: 'Standard 4KB pages require many TLB entries for large memory allocations. With 32GB shared_buffers, that is ~8M page table entries. Huge pages (2MB) reduce this to ~16K entries, dramatically reducing TLB misses. The performance improvement is most noticeable with shared_buffers > 8GB and memory-intensive workloads.', codeSnippet: "-- Step 1: Configure Linux huge pages\n-- Calculate needed pages:\n-- shared_buffers = 32GB = 32768MB\n-- Huge page size = 2MB\n-- Pages needed = 32768/2 + overhead = ~16500\nsudo sysctl -w vm.nr_hugepages=16500\nsudo sh -c 'echo vm.nr_hugepages=16500 >> /etc/sysctl.conf'\n\n-- Step 2: Enable in PostgreSQL:\nALTER SYSTEM SET huge_pages = 'on';\n-- Options: 'off', 'on' (fail if unavailable), 'try' (fallback)\n\n-- Step 3: Restart PostgreSQL\nsudo systemctl restart postgresql\n\n-- Verify:\nSHOW huge_pages;\n-- Check Linux: grep Huge /proc/meminfo", tags: ['admin', 'huge-pages', 'memory', 'performance'] },
  { id: 'pg-admin-l4-019', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Huge Pages', question: 'How do you calculate the correct number of huge pages for PostgreSQL on Linux?', options: ['Just set a large number', 'Calculate by dividing the PostgreSQL shared memory segment size (from pg_shmem_allocations or /proc/PID/status VmPeak) by the huge page size (usually 2MB), then add a small margin — setting too few causes startup failure when huge_pages = on', 'Use the default Linux value', 'PostgreSQL calculates it automatically'], correctAnswer: 1, explanation: 'The shared memory segment includes shared_buffers plus other shared memory allocations (~200-500MB overhead). Check the actual requirement from a running instance via /proc/<postmaster_pid>/status (VmPeak), or use pg_shmem_allocations in PG 12+. Divide by huge page size and add 5-10% margin.', codeSnippet: "-- Method 1: From running PostgreSQL (PG 12+)\nSELECT sum(size) AS total_shared_mem,\n  pg_size_pretty(sum(size)) AS pretty_size\nFROM pg_shmem_allocations;\n\n-- Method 2: From /proc (Linux)\n-- Get postmaster PID:\nSELECT pg_backend_pid();  -- then find postmaster\nhead -1 $PGDATA/postmaster.pid\n-- Check: grep VmPeak /proc/<PID>/status\n\n-- Method 3: Calculate\n-- shared_buffers(32GB) + overhead(~500MB) = ~32.5GB\n-- 32500MB / 2MB = 16250 + 5% margin = ~17063\nsudo sysctl -w vm.nr_hugepages=17063\n\n-- Verify allocation:\n-- grep Huge /proc/meminfo\n-- HugePages_Total: 17063\n-- HugePages_Free:  500  (some in use)", tags: ['admin', 'huge-pages', 'linux', 'shared-memory'] },
  { id: 'pg-admin-l4-020', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Huge Pages', question: 'What is the difference between huge_pages = on and huge_pages = try?', options: ['They behave identically', 'With huge_pages = on, PostgreSQL fails to start if huge pages cannot be allocated; with huge_pages = try, PostgreSQL attempts to use huge pages but falls back to regular pages if unavailable — use "on" in production to ensure consistent performance', 'try is deprecated', 'on uses 1GB pages, try uses 2MB pages'], correctAnswer: 2, explanation: 'huge_pages = try is the safe default that allows PostgreSQL to start even if huge pages are not configured. However, in production you want huge_pages = on to guarantee huge pages are used — falling back silently to regular pages could cause unexpected performance degradation. Always verify huge page availability before setting to "on".', codeSnippet: "-- Production: fail if huge pages unavailable\nALTER SYSTEM SET huge_pages = 'on';\n-- PostgreSQL will NOT start without huge pages\n\n-- Development/testing: try but fallback\nALTER SYSTEM SET huge_pages = 'try';\n-- PostgreSQL starts with or without huge pages\n\n-- Disable (not recommended for large instances)\nALTER SYSTEM SET huge_pages = 'off';\n\n-- Check if huge pages are in use:\n-- grep Huge /proc/meminfo\n-- HugePages_Free < HugePages_Total means in use\n\nSHOW huge_pages;  -- current setting", tags: ['admin', 'huge-pages', 'configuration', 'production'] },
  { id: 'pg-admin-l4-021', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'What do the sent_lsn, write_lsn, flush_lsn, and replay_lsn columns in pg_stat_replication represent?', options: ['They track query execution stages', 'sent_lsn is the last WAL position sent by the primary; write_lsn is what the standby wrote to OS; flush_lsn is what the standby flushed to disk; replay_lsn is what the standby applied — each represents a successive stage of replication with increasing lag', 'They track checkpoint positions', 'They represent backup progress stages'], correctAnswer: 1, explanation: 'These four LSN columns represent the replication pipeline stages: sent (network send buffer) → write (standby OS buffer) → flush (standby disk) → replay (standby applied). The difference between consecutive stages indicates where lag accumulates: network, standby I/O write, standby I/O flush, or standby replay speed.', codeSnippet: "SELECT pid, application_name, client_addr,\n  state, sync_state,\n  sent_lsn,\n  write_lsn,\n  flush_lsn,\n  replay_lsn,\n  -- Lag at each stage:\n  pg_wal_lsn_diff(sent_lsn, write_lsn) AS write_lag_bytes,\n  pg_wal_lsn_diff(write_lsn, flush_lsn) AS flush_lag_bytes,\n  pg_wal_lsn_diff(flush_lsn, replay_lsn) AS replay_lag_bytes,\n  -- Total lag:\n  pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn)\n    AS total_lag_bytes,\n  -- Time-based lag (PG 10+):\n  write_lag, flush_lag, replay_lag\nFROM pg_stat_replication;", tags: ['admin', 'pg-stat-replication', 'monitoring', 'lsn'] },
  { id: 'pg-admin-l4-022', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you detect a standby that has fallen significantly behind?', options: ['Check the standby error log', 'Monitor pg_stat_replication on the primary for large differences between pg_current_wal_lsn() and replay_lsn, and use the write_lag/flush_lag/replay_lag interval columns to measure time-based delay — set up alerts when lag exceeds your RPO threshold', 'Check pg_stat_activity on the standby', 'Use pg_stat_database'], correctAnswer: 1, explanation: 'Compare current WAL position with replay_lsn to get byte-based lag. The time-based columns (PG 10+) show actual delay duration. Set monitoring alerts based on your Recovery Point Objective (RPO). Common thresholds: warn at 100MB or 30s lag, critical at 1GB or 5 minutes. Consider both bytes and time.', codeSnippet: "-- Comprehensive replication lag monitoring query\nSELECT application_name,\n  client_addr,\n  state,\n  pg_size_pretty(\n    pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn)\n  ) AS total_lag,\n  replay_lag,\n  CASE\n    WHEN pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn)\n      > 1073741824 THEN 'CRITICAL'\n    WHEN pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn)\n      > 104857600 THEN 'WARNING'\n    ELSE 'OK'\n  END AS status\nFROM pg_stat_replication\nORDER BY pg_wal_lsn_diff(\n  pg_current_wal_lsn(), replay_lsn\n) DESC;", tags: ['admin', 'pg-stat-replication', 'lag-detection', 'alerting'] },
  { id: 'pg-admin-l4-023', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'What does the state column in pg_stat_replication indicate?', options: ['The health of the primary server', 'It shows the current state of the WAL sender process: startup (connecting), catchup (standby catching up with primary), streaming (real-time replication), backup (pg_basebackup in progress), or stopping (shutting down)', 'Whether queries are running on the standby', 'The checkpoint state'], correctAnswer: 1, explanation: 'The WAL sender state transitions from startup → catchup → streaming during normal operation. A standby in "catchup" is replaying WAL to reach the current position. Once caught up, it enters "streaming" state. "backup" indicates a pg_basebackup connection. Monitor for standbys stuck in "catchup" which may indicate issues.', codeSnippet: "-- Check WAL sender states\nSELECT pid, application_name, client_addr,\n  state,\n  CASE state\n    WHEN 'streaming' THEN 'Normal - real-time replication'\n    WHEN 'catchup' THEN 'Catching up - standby behind'\n    WHEN 'startup' THEN 'Initializing connection'\n    WHEN 'backup' THEN 'pg_basebackup in progress'\n    WHEN 'stopping' THEN 'Shutting down'\n  END AS state_description,\n  backend_start,\n  now() - backend_start AS connection_age\nFROM pg_stat_replication;", tags: ['admin', 'pg-stat-replication', 'wal-sender', 'state'] },
  { id: 'pg-admin-l4-024', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you monitor replication slot disk usage and identify inactive slots?', options: ['Check pg_stat_database', 'Query pg_replication_slots for inactive slots and calculate retained WAL using pg_wal_lsn_diff between current WAL position and restart_lsn — inactive slots prevent WAL cleanup and can fill disk space rapidly', 'Use pg_stat_user_tables', 'Replication slots do not use disk'], correctAnswer: 1, explanation: 'Each replication slot pins WAL from its restart_lsn, preventing cleanup. Inactive slots (active = false) are especially dangerous as they accumulate WAL indefinitely. Regular monitoring should alert on: inactive slots older than a threshold, slots retaining more than X GB of WAL, and slots approaching max_slot_wal_keep_size.', codeSnippet: "-- Monitor all replication slots\nSELECT slot_name, slot_type, plugin, active,\n  active_pid,\n  pg_size_pretty(\n    pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)\n  ) AS retained_wal,\n  age(now(), COALESCE(\n    pg_stat_get_replication_slot(slot_name).stats_reset,\n    '2000-01-01'::timestamptz\n  )) AS slot_age,\n  wal_status  -- PG 13+: reserved/extended/unreserved/lost\nFROM pg_replication_slots\nORDER BY\n  pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) DESC;\n\n-- Drop dangerous inactive slot:\n-- SELECT pg_drop_replication_slot('inactive_slot');", tags: ['admin', 'replication-slots', 'monitoring', 'disk-usage'] },
  { id: 'pg-admin-l4-025', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What are the three essential components needed for point-in-time recovery (PITR)?', options: ['pg_dump, pg_restore, and a timestamp', 'A base backup (pg_basebackup), continuous WAL archive files (from archive_command or pg_receivewal), and a recovery target specification (timestamp, XID, LSN, or named restore point) — all three are required for successful PITR', 'Only a full backup is needed', 'pg_dump and WAL files'], correctAnswer: 1, explanation: 'PITR works by restoring a base backup, then replaying archived WAL files up to the specified recovery point. Missing any component fails recovery: without the base backup there is no starting point, without WAL files there are gaps in changes, without a target the recovery replays all available WAL.', codeSnippet: "-- Component 1: Continuous WAL archiving\narchive_mode = on\narchive_command = 'cp %p /archive/%f'\n\n-- Component 2: Base backup\npg_basebackup -D /backup/base -Fp -Xs -P\n\n-- Component 3: Recovery target\n-- In postgresql.conf (or postgresql.auto.conf):\nrestore_command = 'cp /archive/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_action = 'promote'\n\n-- Create named restore point before risky operations:\nSELECT pg_create_restore_point('before_migration');\n-- Then: recovery_target_name = 'before_migration'", tags: ['admin', 'pitr', 'backup', 'wal-archiving'] },
  { id: 'pg-admin-l4-026', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is the difference between recovery_target_time, recovery_target_xid, and recovery_target_lsn?', options: ['They are aliases for the same setting', 'recovery_target_time stops at a wall-clock timestamp, recovery_target_xid stops after a specific transaction ID commits, and recovery_target_lsn stops at a specific WAL byte position — each provides different precision for targeting the recovery point', 'Only recovery_target_time works', 'They control backup scheduling'], correctAnswer: 1, explanation: 'recovery_target_time is most common (recover to a known time). recovery_target_xid targets a specific transaction (useful when you know which transaction caused the problem). recovery_target_lsn targets a WAL position (most precise). recovery_target_name targets a named restore point. Only one target can be active.', codeSnippet: "-- Recover to a specific time:\nrecovery_target_time = '2024-06-15 14:30:00+00'\nrecovery_target_inclusive = true  -- include or exclude\n\n-- Recover to a specific transaction:\nrecovery_target_xid = '12345678'\n-- Recovers up to and including this XID\n\n-- Recover to a WAL position:\nrecovery_target_lsn = '0/1A2B3C4D'\n\n-- Recover to a named restore point:\nrecovery_target_name = 'before_migration'\n\n-- What to do when target is reached:\nrecovery_target_action = 'promote'  -- or 'pause', 'shutdown'", tags: ['admin', 'pitr', 'recovery-target', 'wal'] },
  { id: 'pg-admin-l4-027', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How does recovery_target_action control behavior when the recovery target is reached?', options: ['It determines the backup action', 'recovery_target_action = promote makes the server open for read-write after reaching the target; pause keeps it in recovery (read-only) for verification before manual promotion; shutdown stops the server for inspection — pause is safest for critical recoveries', 'It sets the archive cleanup action', 'It controls replication failover'], correctAnswer: 2, explanation: 'promote (default in PG 12+) immediately makes the server writable. pause keeps recovery paused so you can inspect the data and decide whether to promote or continue. shutdown stops the server cleanly for offline inspection. For critical PITR, use pause to verify the data before committing to the recovery point.', codeSnippet: "-- Safe recovery with verification:\nrestore_command = 'cp /archive/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_action = 'pause'\n-- Server stays read-only; verify data, then:\nSELECT pg_wal_replay_resume();  -- continue replay\n-- Or: SELECT pg_promote();  -- accept this point\n\n-- Auto-promote (most common):\nrecovery_target_action = 'promote'\n\n-- Shutdown for offline inspection:\nrecovery_target_action = 'shutdown'", tags: ['admin', 'pitr', 'recovery-target-action', 'promote'] },
  { id: 'pg-admin-l4-028', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you perform PITR using pg_receivewal instead of archive_command?', options: ['pg_receivewal is only for monitoring', 'pg_receivewal is a streaming client that continuously receives WAL from the primary via replication protocol, providing lower RPO than archive_command since it does not wait for WAL segment completion — it writes partial WAL segments in real-time', 'pg_receivewal replaces pg_basebackup', 'It requires logical replication'], correctAnswer: 1, explanation: 'archive_command only archives complete 16MB WAL segments, meaning up to 16MB of recent changes could be lost. pg_receivewal streams WAL in real-time to a directory, including partial segments. This provides near-zero RPO. Use --slot to create a replication slot and prevent WAL removal during pg_receivewal restarts.', codeSnippet: "-- Start pg_receivewal with replication slot:\npg_receivewal -h primary -D /wal_archive/ \\\n  -U repl_user --slot=wal_receiver \\\n  --create-slot\n  --synchronous  -- flush every record\n\n-- With compression (PG 15+):\npg_receivewal -D /wal_archive/ \\\n  --compress=lz4 --slot=wal_receiver\n\n-- For PITR, use the WAL archive:\nrestore_command = 'cp /wal_archive/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_action = 'pause'\n\n-- Partial WAL files have .partial suffix\n-- They contain the most recent changes", tags: ['admin', 'pitr', 'pg-receivewal', 'wal-streaming'] },
  { id: 'pg-admin-l4-029', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is pg_rewind and when is it used instead of a full base backup?', options: ['It rewinds query execution plans', 'pg_rewind synchronizes a diverged PostgreSQL data directory with a source server by copying only the changed blocks since the timeline divergence point — it is much faster than pg_basebackup for reconfiguring an old primary as a standby after failover', 'It reverts schema changes', 'It rewinds WAL archiving'], correctAnswer: 1, explanation: 'After a failover, the old primary has WAL that diverged from the new timeline. pg_rewind reads the WAL on both sides to identify changed pages and copies only those pages from the source. This is orders of magnitude faster than a full pg_basebackup for large databases. Requires wal_log_hints = on or data checksums.', codeSnippet: "-- Prerequisites:\nwal_log_hints = on  -- or use data checksums\nfull_page_writes = on  -- must be on (default)\n\n-- After failover, rewind old primary:\npg_rewind --target-pgdata=/old_primary/data \\\n  --source-server='host=new_primary port=5432 \\\n  user=repl_user dbname=postgres'\n\n-- Or use local source:\npg_rewind --target-pgdata=/old_primary/data \\\n  --source-pgdata=/new_primary/data\n\n-- Then configure as standby:\ntouch /old_primary/data/standby.signal\n-- Set primary_conninfo in postgresql.auto.conf\npg_ctl start -D /old_primary/data", tags: ['admin', 'pg-rewind', 'failover', 'standby-reconfiguration'] },
  { id: 'pg-admin-l4-030', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'What are the two modes of pg_upgrade and their trade-offs?', options: ['Online and offline modes', 'Copy mode (--copy or default) physically copies all data files which is safe but slow for large databases; link mode (--link) creates hard links to data files which is nearly instant but makes the old cluster unusable — link mode requires same filesystem for both clusters', 'Fast and slow modes', 'Parallel and sequential modes'], correctAnswer: 1, explanation: 'Copy mode duplicates all files, preserving the old cluster as a rollback option but requiring disk space for both. Link mode creates hard links, completing in seconds even for TB-scale databases, but the old cluster cannot be started after the new one writes to linked files. Clone mode (PG 17+) uses filesystem reflinks for copy-on-write.', codeSnippet: "-- Copy mode (safe, slow):\npg_upgrade \\\n  --old-datadir=/pg15/data \\\n  --new-datadir=/pg16/data \\\n  --old-bindir=/pg15/bin \\\n  --new-bindir=/pg16/bin \\\n  --check  -- dry run first!\n\n-- Link mode (fast, destructive to old cluster):\npg_upgrade \\\n  --old-datadir=/pg15/data \\\n  --new-datadir=/pg16/data \\\n  --old-bindir=/pg15/bin \\\n  --new-bindir=/pg16/bin \\\n  --link\n\n-- Clone mode (PG 17+, fast + safe):\npg_upgrade ... --clone\n-- Uses filesystem reflinks (copy-on-write)", tags: ['admin', 'pg-upgrade', 'major-version-upgrade', 'link-mode'] },
  { id: 'pg-admin-l4-031', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'What pre-upgrade checks should you perform before running pg_upgrade?', options: ['No checks are needed', 'Run pg_upgrade --check to verify compatibility, ensure all extensions are available in the new version, verify data checksums match, check for deprecated features/data types, review the release notes for breaking changes, and take a full backup', 'Only check disk space', 'Just run pg_upgrade directly'], correctAnswer: 1, explanation: 'pg_upgrade --check performs a dry run that validates: binary compatibility, extension availability, data type compatibility, locale settings, and more. Additionally, manually check: deprecated features removed in the new version, extension compatibility, application connection string updates, and always maintain a rollback backup.', codeSnippet: "-- Step 1: Check compatibility (dry run)\npg_upgrade --check \\\n  --old-datadir=/pg15/data \\\n  --new-datadir=/pg16/data \\\n  --old-bindir=/pg15/bin \\\n  --new-bindir=/pg16/bin\n\n-- Step 2: Check extension availability\nSELECT name, default_version, installed_version\nFROM pg_available_extensions\nWHERE installed_version IS NOT NULL;\n\n-- Step 3: Check for deprecated items\n-- Review: postgresql.org/docs/16/release-16.html\n\n-- Step 4: Full backup\npg_dumpall > /backup/pre_upgrade_dump.sql\npg_basebackup -D /backup/base -Fp -Xs -P", tags: ['admin', 'pg-upgrade', 'pre-upgrade', 'compatibility-check'] },
  { id: 'pg-admin-l4-032', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'Why is running ANALYZE (or vacuumdb --analyze-in-stages) important after pg_upgrade?', options: ['It cleans up old data files', 'pg_upgrade does not transfer optimizer statistics (pg_statistic) — without running ANALYZE on the new cluster, the query planner uses default estimates leading to poor query plans; --analyze-in-stages provides progressively more accurate statistics starting quickly', 'It rebuilds all indexes', 'ANALYZE is run automatically by pg_upgrade'], correctAnswer: 1, explanation: 'pg_upgrade transfers data but not optimizer statistics. The planner relies on statistics for choosing join methods, scan types, and row estimates. vacuumdb --analyze-in-stages runs ANALYZE three times with increasing default_statistics_target (1, 10, default), providing usable statistics quickly while refining them.', codeSnippet: "-- After pg_upgrade completes:\n\n-- Option 1: Quick staged approach (recommended)\nvacuumdb --all --analyze-in-stages\n-- Stage 1: target=1  (very fast, basic stats)\n-- Stage 2: target=10 (quick, better stats)\n-- Stage 3: target=default (full statistics)\n\n-- Option 2: Full analyze (slower but complete)\nvacuumdb --all --analyze-only --jobs=4\n\n-- Option 3: Analyze specific large/critical tables first\nANALYZE VERBOSE large_table;\nANALYZE VERBOSE critical_table;\n\n-- The generated script:\n-- pg_upgrade creates analyze_new_cluster.sh\n./analyze_new_cluster.sh", tags: ['admin', 'pg-upgrade', 'analyze', 'statistics'] },
  { id: 'pg-admin-l4-033', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'How can you minimize downtime during a major version upgrade with pg_upgrade?', options: ['pg_upgrade has no downtime', 'Use pg_upgrade with --link mode for near-instant file linking, perform pre-upgrade steps (install new version, init new cluster, run --check) beforehand, use logical replication to pre-migrate data, or combine pg_upgrade with a standby promotion strategy', 'Use pg_dump/pg_restore instead', 'Upgrade in place without stopping'], correctAnswer: 1, explanation: 'Key strategies: (1) Link mode reduces file copy time to seconds. (2) Prepare everything in advance (install, initdb, --check). (3) For zero-downtime: set up logical replication from old to new version, switch applications. (4) For standbys: upgrade primary with --link, rebuild standbys with pg_basebackup. Total downtime can be minutes even for TB databases.', codeSnippet: "-- Minimal downtime upgrade procedure:\n\n-- 1. Pre-upgrade (no downtime):\nsudo apt install postgresql-16  -- install new version\npg_lsclusters  -- verify both versions\npg_upgrade --check ...  -- validate\n\n-- 2. Upgrade (downtime starts):\nsudo systemctl stop postgresql@15-main\npg_upgrade --link \\\n  --old-datadir=... --new-datadir=... \\\n  --old-bindir=... --new-bindir=...\n  --jobs=4  -- parallel processing\n\n-- 3. Post-upgrade (downtime ends):\nsudo systemctl start postgresql@16-main\n-- Start analyze in background:\nvacuumdb --all --analyze-in-stages &\n\n-- 4. Rebuild standbys:\npg_basebackup -h primary -D /standby/data -Xs -P", tags: ['admin', 'pg-upgrade', 'downtime', 'upgrade-strategy'] },
  { id: 'pg-admin-l4-034', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you use logical replication for zero-downtime major version upgrades?', options: ['Logical replication cannot cross versions', 'Set up logical replication from the old version to the new version, let subscriber catch up, then switch application connections to the new server — logical replication supports cross-version replication making this possible without pg_upgrade downtime', 'Use physical replication instead', 'Export data with COPY commands'], correctAnswer: 1, explanation: 'Logical replication works across PostgreSQL versions (10+). Steps: (1) Set up new version server, (2) Create publication on old server, (3) Create subscription on new server, (4) Wait for initial sync + catch up, (5) Verify data, (6) Switch application connections. Sequence/serial columns and DDL need manual handling.', codeSnippet: "-- On OLD server (PG 15):\nALTER SYSTEM SET wal_level = 'logical';\n-- Restart required\n\nCREATE PUBLICATION upgrade_pub FOR ALL TABLES;\n\n-- On NEW server (PG 16):\n-- Create same schema (pg_dump --schema-only)\nCREATE SUBSCRIPTION upgrade_sub\n  CONNECTION 'host=old_server dbname=mydb user=repl'\n  PUBLICATION upgrade_pub;\n\n-- Monitor sync progress:\nSELECT * FROM pg_subscription_rel;\n-- Wait for srsubstate = 'r' (ready) on all tables\n\n-- Switch applications to new server\n-- Then on old server:\nDROP PUBLICATION upgrade_pub;", tags: ['admin', 'logical-replication', 'zero-downtime', 'major-upgrade'] },
  { id: 'pg-admin-l4-035', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'What is the autovacuum_naptime parameter and how does it affect vacuum scheduling?', options: ['It sets how long each vacuum runs', 'autovacuum_naptime (default 1 minute) is the delay between autovacuum rounds where the launcher checks all databases for tables needing vacuum — reducing it makes the launcher check more frequently, important for databases with many tables that change rapidly', 'It sets the sleep time during vacuum', 'It delays vacuum after server start'], correctAnswer: 1, explanation: 'The autovacuum launcher wakes every autovacuum_naptime seconds, checks each database for tables exceeding vacuum/analyze thresholds, and launches workers. With many databases, the launcher cycles through them (naptime * num_databases between checks of the same database). Reducing naptime ensures timely vacuum for rapidly changing tables.', codeSnippet: "-- Default: check every 60 seconds\nSHOW autovacuum_naptime;  -- 1min\n\n-- More responsive for busy databases:\nALTER SYSTEM SET autovacuum_naptime = '15s';\nSELECT pg_reload_conf();\n\n-- Note: with multiple databases, effective interval is:\n-- autovacuum_naptime * number_of_databases\n-- 5 databases with 1min naptime = 5 min per database\n\n-- Monitor autovacuum launcher:\nSELECT pid, backend_type, state\nFROM pg_stat_activity\nWHERE backend_type = 'autovacuum launcher';", tags: ['admin', 'autovacuum', 'naptime', 'scheduling'] },
  { id: 'pg-admin-l4-036', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How do you diagnose and fix autovacuum workers being blocked by long-running transactions?', options: ['Autovacuum is never blocked', 'Long-running transactions hold back the xmin horizon preventing vacuum from removing dead tuples visible to those transactions — monitor pg_stat_activity for old xmin values and consider statement_timeout or idle_in_transaction_session_timeout to limit damage', 'Increase autovacuum_max_workers', 'Disable the blocking transactions'], correctAnswer: 1, explanation: 'Vacuum can only remove tuples invisible to ALL current transactions. A single old transaction prevents cleanup of all newer dead tuples. idle_in_transaction_session_timeout (PG 9.6+) automatically terminates idle transactions. Also monitor prepared transactions (pg_prepared_xacts) and replication slots which can hold back xmin.', codeSnippet: "-- Find transactions blocking vacuum:\nSELECT pid, usename, state,\n  backend_xmin,\n  age(backend_xmin) AS xmin_age,\n  now() - xact_start AS xact_duration,\n  query\nFROM pg_stat_activity\nWHERE backend_xmin IS NOT NULL\nORDER BY age(backend_xmin) DESC;\n\n-- Set limits to prevent this:\nALTER SYSTEM SET idle_in_transaction_session_timeout = '5min';\nALTER SYSTEM SET statement_timeout = '30min';\n\n-- Check for orphaned prepared transactions:\nSELECT * FROM pg_prepared_xacts;\n\n-- Check replication slot xmin:\nSELECT slot_name, xmin, catalog_xmin,\n  age(xmin) AS xmin_age\nFROM pg_replication_slots;", tags: ['admin', 'autovacuum', 'blocker', 'xmin-horizon'] },
  { id: 'pg-admin-l4-037', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'What is the difference between autovacuum_vacuum_insert_scale_factor and autovacuum_vacuum_scale_factor?', options: ['They are the same parameter', 'autovacuum_vacuum_insert_scale_factor (PG 13+) triggers vacuum based on INSERT count to freeze new tuples and update the visibility map, while autovacuum_vacuum_scale_factor triggers based on dead tuples from UPDATE/DELETE — insert-only tables previously never got vacuumed', 'Insert scale factor only affects ANALYZE', 'Insert scale factor controls index creation'], correctAnswer: 1, explanation: 'Before PG 13, insert-only tables were never autovacuumed since there are no dead tuples. But they still need freezing and visibility map updates (for index-only scans). autovacuum_vacuum_insert_threshold + insert_scale_factor * reltuples triggers vacuum based on inserts. Default insert_scale_factor is 0.2 (20%).', codeSnippet: "-- PG 13+ insert-based vacuum trigger:\nSHOW autovacuum_vacuum_insert_threshold;  -- 1000\nSHOW autovacuum_vacuum_insert_scale_factor;  -- 0.2\n-- Triggers when: inserts >= 1000 + 0.2 * reltuples\n\n-- Per-table override for append-only tables:\nALTER TABLE audit_log SET (\n  autovacuum_vacuum_insert_scale_factor = 0.05,\n  autovacuum_vacuum_insert_threshold = 500\n);\n\n-- Disable insert-based vacuum (not recommended):\nALTER TABLE static_lookup SET (\n  autovacuum_vacuum_insert_threshold = -1\n);\n\n-- Monitor inserts since last vacuum:\nSELECT relname, n_ins_since_vacuum\nFROM pg_stat_user_tables\nORDER BY n_ins_since_vacuum DESC;", tags: ['admin', 'autovacuum', 'insert-scale-factor', 'pg13'] },
  { id: 'pg-admin-l4-038', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you use pg_stat_wal_receiver on a standby to monitor incoming replication?', options: ['pg_stat_wal_receiver does not exist', 'pg_stat_wal_receiver on the standby shows the WAL receiver process status including connection info, last received/flushed LSN, received timeline, sender host, and the conninfo used — it complements pg_stat_replication on the primary', 'It only works on the primary', 'Use pg_stat_activity instead'], correctAnswer: 1, explanation: 'pg_stat_wal_receiver provides the standby perspective of replication. Key columns: status (streaming/stopped), received_lsn, flushed_lsn, sender_host, sender_port, slot_name, conninfo. Compare received_lsn vs flushed_lsn to see local I/O lag. If status is not "streaming", investigate connectivity issues.', codeSnippet: "-- On the STANDBY server:\nSELECT status,\n  receive_start_lsn,\n  received_lsn,\n  flushed_lsn,\n  received_tli,\n  last_msg_send_time,\n  last_msg_receipt_time,\n  latest_end_lsn,\n  latest_end_time,\n  slot_name,\n  sender_host,\n  sender_port,\n  conninfo\nFROM pg_stat_wal_receiver;\n\n-- Check if standby is in recovery:\nSELECT pg_is_in_recovery();  -- true on standby\n\n-- Check replay progress:\nSELECT pg_last_wal_receive_lsn(),\n  pg_last_wal_replay_lsn(),\n  pg_last_xact_replay_timestamp();", tags: ['admin', 'pg-stat-wal-receiver', 'standby', 'monitoring'] },
  { id: 'pg-admin-l4-039', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'What is bidirectional logical replication and what challenges does it present?', options: ['It is built into PostgreSQL natively', 'Bidirectional (multi-master) logical replication is achieved by creating publications and subscriptions in both directions between servers — the main challenges are conflict resolution, avoiding infinite replication loops, and handling DDL synchronization', 'It requires physical replication', 'It is not possible with PostgreSQL'], correctAnswer: 1, explanation: 'Bidirectional replication creates a multi-master setup. Each server publishes and subscribes. Key challenges: (1) Replication loops — use origin tracking to skip changes from the remote, (2) Conflicts — same row modified on both servers simultaneously, (3) Sequences — must use non-overlapping ranges, (4) DDL must be applied manually to all nodes.', codeSnippet: "-- Server A:\nCREATE PUBLICATION pub_a FOR ALL TABLES;\nCREATE SUBSCRIPTION sub_a\n  CONNECTION 'host=server_b ...'\n  PUBLICATION pub_b\n  WITH (origin = 'none');  -- PG 16+: skip remote origins\n\n-- Server B:\nCREATE PUBLICATION pub_b FOR ALL TABLES;\nCREATE SUBSCRIPTION sub_b\n  CONNECTION 'host=server_a ...'\n  PUBLICATION pub_a\n  WITH (origin = 'none');  -- prevents loops\n\n-- Use non-overlapping sequences:\n-- Server A: odd IDs\nALTER SEQUENCE users_id_seq INCREMENT 2 START 1;\n-- Server B: even IDs\nALTER SEQUENCE users_id_seq INCREMENT 2 START 2;", tags: ['admin', 'logical-replication', 'bidirectional', 'multi-master'] },
  { id: 'pg-admin-l4-040', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you handle initial data synchronization when adding a subscription?', options: ['Data must be manually loaded first', 'CREATE SUBSCRIPTION automatically performs an initial table synchronization (copy_data = true by default) using COPY to transfer existing data before switching to streaming changes — you can disable this with copy_data = false if tables are pre-loaded', 'Use pg_dump to transfer data', 'Initial sync is not possible'], correctAnswer: 1, explanation: 'By default, CREATE SUBSCRIPTION copies existing table data using parallel COPY workers (one per table). This can be resource-intensive for large tables. Options: copy_data = false (skip if data exists), streaming = on (PG 14+, apply large transactions as they stream). Monitor progress via pg_stat_subscription_stats and pg_subscription_rel.', codeSnippet: "-- Default: automatic initial sync\nCREATE SUBSCRIPTION my_sub\n  CONNECTION 'host=pub dbname=mydb user=repl'\n  PUBLICATION my_pub;\n  -- copy_data = true (default)\n\n-- Skip initial sync (data pre-loaded):\nCREATE SUBSCRIPTION my_sub\n  CONNECTION '...'\n  PUBLICATION my_pub\n  WITH (copy_data = false);\n\n-- Monitor initial sync progress:\nSELECT srrelid::regclass AS table_name,\n  srsubstate AS state\n  -- i=init, d=data copy, f=finished, r=ready, s=sync\nFROM pg_subscription_rel;\n\n-- PG 14+: stream large transactions\nCREATE SUBSCRIPTION my_sub\n  CONNECTION '...'\n  PUBLICATION my_pub\n  WITH (streaming = on);", tags: ['admin', 'logical-replication', 'initial-sync', 'copy-data'] },
  { id: 'pg-admin-l4-041', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Huge Pages', question: 'How do you configure Transparent Huge Pages (THP) vs explicit huge pages for PostgreSQL?', options: ['THP and huge pages are the same', 'Explicit huge pages (hugetlbfs) are preferred for PostgreSQL as they provide predictable allocation at startup; Transparent Huge Pages should be disabled as THP can cause latency spikes due to background page compaction, defragmentation, and allocation stalls', 'THP is always better for databases', 'Neither should be used'], correctAnswer: 1, explanation: 'Explicit huge pages are allocated at boot/configuration time and are guaranteed available. THP allocates dynamically, which can cause: compaction stalls (latency spikes), memory fragmentation, unpredictable allocation failures, and khugepaged CPU overhead. Most database vendors recommend disabling THP for database workloads.', codeSnippet: "-- Disable Transparent Huge Pages (Linux):\nsudo sh -c 'echo never > /sys/kernel/mm/transparent_hugepage/enabled'\nsudo sh -c 'echo never > /sys/kernel/mm/transparent_hugepage/defrag'\n\n-- Make persistent via grub:\n# GRUB_CMDLINE_LINUX=\"transparent_hugepage=never\"\n\n-- Enable explicit huge pages:\nsudo sysctl -w vm.nr_hugepages=16500\n\n-- PostgreSQL config:\nhuge_pages = 'on'  -- use explicit huge pages\n\n-- Verify THP is disabled:\ncat /sys/kernel/mm/transparent_hugepage/enabled\n# [never] always madvise\n\n-- Verify explicit huge pages:\ngrep Huge /proc/meminfo", tags: ['admin', 'huge-pages', 'thp', 'linux-tuning'] },
  { id: 'pg-admin-l4-042', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'How do you use pg_basebackup with tablespace mapping?', options: ['Tablespaces are ignored during backup', 'Use --tablespace-mapping (-T) to remap tablespace directories during backup, specifying old=new path pairs — essential when restoring to a different server where tablespace paths differ or do not exist', 'Tablespaces are automatically remapped', 'Use ALTER TABLESPACE after restore'], correctAnswer: 1, explanation: 'PostgreSQL tablespaces reference absolute paths. When backing up to a different server, those paths may not exist or may conflict. --tablespace-mapping remaps each tablespace directory. Multiple -T flags can be used for multiple tablespaces. In tar format (-Ft), tablespaces become separate tar files.', codeSnippet: "-- Backup with tablespace remapping:\npg_basebackup -h primary -D /backup/data \\\n  -T /old/fast_ssd=/new/fast_ssd \\\n  -T /old/archive_hdd=/new/archive_hdd \\\n  -Fp -Xs -P\n\n-- Multiple tablespaces:\npg_basebackup -D /backup/data \\\n  -T /data/ts_idx=/restore/ts_idx \\\n  -T /data/ts_data=/restore/ts_data \\\n  -Fp -Xs\n\n-- Tar format creates separate files:\npg_basebackup -D /backup/ -Ft -Xs\n-- Creates: base.tar, <oid>.tar (per tablespace)\n\n-- List tablespaces:\nSELECT spcname, pg_tablespace_location(oid)\nFROM pg_tablespace\nWHERE spcname NOT IN ('pg_default', 'pg_global');", tags: ['admin', 'pg-basebackup', 'tablespace', 'mapping'] },
  { id: 'pg-admin-l4-043', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'What is the two_phase option in logical replication subscriptions?', options: ['It splits replication into two phases', 'The two_phase option (PG 15+) enables prepared transaction support in logical replication — when the publisher uses PREPARE TRANSACTION, the subscriber also prepares and later commits/rolls back, maintaining distributed transaction consistency', 'It runs replication in parallel', 'It enables bidirectional replication'], correctAnswer: 1, explanation: 'Without two_phase, prepared transactions on the publisher are decoded and applied only at COMMIT PREPARED time on the subscriber. With two_phase = true, the subscriber prepares the transaction when the publisher prepares it, allowing distributed transaction coordination. This is important for applications using two-phase commit protocols.', codeSnippet: "-- Create subscription with two-phase commit support:\nCREATE SUBSCRIPTION my_sub\n  CONNECTION 'host=pub dbname=mydb user=repl'\n  PUBLICATION my_pub\n  WITH (two_phase = true);\n\n-- On publisher:\nBEGIN;\nINSERT INTO orders VALUES (1, 'item', 99.99);\nPREPARE TRANSACTION 'order_tx_001';\n-- Subscriber also prepares\n\n-- Later:\nCOMMIT PREPARED 'order_tx_001';\n-- Subscriber also commits\n\n-- Check prepared transactions on subscriber:\nSELECT * FROM pg_prepared_xacts;", tags: ['admin', 'logical-replication', 'two-phase', 'prepared-transactions'] },
  { id: 'pg-admin-l4-044', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you measure the time delay of replication rather than just byte lag?', options: ['Time delay cannot be measured', 'PG 10+ provides write_lag, flush_lag, and replay_lag interval columns in pg_stat_replication that measure actual time delay at each stage; on standbys, compare pg_last_xact_replay_timestamp() with current time to get overall replay delay', 'Use pg_sleep to measure lag', 'Only byte-based lag is available'], correctAnswer: 1, explanation: 'Byte lag does not indicate time delay (a quiet server may have small byte lag but it could still represent hours of changes). write_lag/flush_lag/replay_lag show actual time intervals. On standbys, now() - pg_last_xact_replay_timestamp() gives overall delay. Note: this can be misleading during low-activity periods.', codeSnippet: "-- On primary: time-based lag columns\nSELECT application_name,\n  write_lag,\n  flush_lag,\n  replay_lag,\n  pg_size_pretty(\n    pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn)\n  ) AS byte_lag\nFROM pg_stat_replication;\n\n-- On standby: overall replay delay\nSELECT now() - pg_last_xact_replay_timestamp()\n  AS replay_delay;\n-- Warning: inaccurate during low-activity periods\n-- (timestamp only updates when transactions replay)\n\n-- Better approach for standbys:\nSELECT CASE\n  WHEN pg_last_wal_receive_lsn() = pg_last_wal_replay_lsn()\n  THEN interval '0'\n  ELSE now() - pg_last_xact_replay_timestamp()\nEND AS lag;", tags: ['admin', 'pg-stat-replication', 'time-lag', 'monitoring'] },
  { id: 'pg-admin-l4-045', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How do you monitor autovacuum progress for long-running vacuums?', options: ['Progress cannot be monitored', 'Query pg_stat_progress_vacuum (PG 9.6+) which shows the current phase, heap blocks scanned/vacuumed, index vacuum count, and dead tuples collected for each active VACUUM operation — useful for estimating completion time of large table vacuums', 'Check the PostgreSQL log only', 'Use pg_stat_activity query column'], correctAnswer: 1, explanation: 'pg_stat_progress_vacuum shows real-time vacuum progress including: phase (scanning heap, vacuuming indexes, etc.), heap_blks_total vs heap_blks_scanned, num_dead_tuples found, and index_vacuum_count (number of index passes). Combined with table size, you can estimate remaining time and detect stuck vacuums.', codeSnippet: "-- Monitor vacuum progress:\nSELECT p.pid, a.query,\n  p.relid::regclass AS table_name,\n  p.phase,\n  p.heap_blks_total,\n  p.heap_blks_scanned,\n  p.heap_blks_vacuumed,\n  round(100.0 * p.heap_blks_scanned /\n    NULLIF(p.heap_blks_total, 0), 1) AS scan_pct,\n  p.index_vacuum_count,\n  p.max_dead_tuples,\n  p.num_dead_tuples\nFROM pg_stat_progress_vacuum p\nJOIN pg_stat_activity a USING (pid);\n\n-- Phases:\n-- initializing, scanning heap, vacuuming indexes,\n-- vacuuming heap, cleaning up indexes,\n-- truncating heap, performing final cleanup", tags: ['admin', 'autovacuum', 'progress-monitoring', 'pg-stat-progress'] },
  { id: 'pg-admin-l4-046', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you set up continuous archiving with pg_receivewal for zero data loss?', options: ['archive_command is sufficient for zero data loss', 'Combine pg_receivewal (streaming WAL to archive in real-time) with a replication slot (to prevent WAL removal) and --synchronous mode (to ensure every WAL record is flushed) — this provides RPO=0 without the latency cost of synchronous replication', 'Zero data loss requires synchronous replication only', 'Use pg_dump for zero data loss'], correctAnswer: 1, explanation: 'archive_command only archives complete 16MB segments, losing up to 16MB of recent WAL. pg_receivewal with --synchronous flushes each WAL record to the archive immediately. A replication slot prevents WAL removal during pg_receivewal restarts. This achieves RPO≈0 for PITR without synchronous standby latency overhead.', codeSnippet: "-- On primary: create replication slot\nSELECT pg_create_physical_replication_slot(\n  'wal_archive_slot', true  -- immediately_reserve\n);\n\n-- Run pg_receivewal:\npg_receivewal \\\n  -h primary -U repl_user \\\n  -D /wal_archive/ \\\n  --slot=wal_archive_slot \\\n  --synchronous \\\n  --no-loop  -- exit on disconnect (use systemd)\n\n-- systemd service for auto-restart:\n# [Service]\n# ExecStart=/usr/bin/pg_receivewal ...\n# Restart=always\n# RestartSec=5\n\n-- Verify WAL is being received:\nls -lt /wal_archive/ | head", tags: ['admin', 'pitr', 'pg-receivewal', 'zero-data-loss'] },
  { id: 'pg-admin-l4-047', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'How does pg_upgrade handle extensions during a major version upgrade?', options: ['Extensions are automatically upgraded', 'pg_upgrade preserves extension installations but does not upgrade extension code — you must install the same or compatible extension packages for the new PostgreSQL version before running pg_upgrade, and run ALTER EXTENSION ... UPDATE after upgrade for version bumps', 'Extensions must be reinstalled manually', 'Extensions are dropped during upgrade'], correctAnswer: 1, explanation: 'pg_upgrade copies the pg_extension catalog entries but relies on the new cluster having the extension files (.so, .sql, .control) available. Install extension packages for the new PG version first. After upgrade, run ALTER EXTENSION name UPDATE to update to the latest extension version if available.', codeSnippet: "-- Before pg_upgrade:\n-- 1. List installed extensions:\nSELECT extname, extversion FROM pg_extension;\n\n-- 2. Install extension packages for new PG version:\nsudo apt install postgresql-16-postgis-3\nsudo apt install postgresql-16-pgvector\n\n-- 3. Run pg_upgrade (extensions are preserved)\npg_upgrade ...\n\n-- After pg_upgrade:\n-- 4. Update extensions to latest versions:\nALTER EXTENSION postgis UPDATE;\nALTER EXTENSION pgvector UPDATE;\n\n-- 5. Verify:\nSELECT extname, extversion FROM pg_extension;\n\n-- Note: pg_upgrade --check warns about\n-- missing extension files", tags: ['admin', 'pg-upgrade', 'extensions', 'compatibility'] },
  { id: 'pg-admin-l4-048', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you replicate partitioned tables with logical replication?', options: ['Partitioned tables cannot be replicated', 'PG 13+ supports publishing partitioned tables directly with publish_via_partition_root option — without it, each partition is published separately; the subscriber can have a different partitioning scheme as long as it can receive the data', 'Only the parent table is replicated', 'Partitions must be converted to regular tables'], correctAnswer: 1, explanation: 'Before PG 13, you had to add each partition individually to the publication. PG 13+ allows adding the partitioned parent table directly. With publish_via_partition_root = true, changes appear to come from the root table (useful when subscriber has different partitioning). Without it, changes reference individual partitions.', codeSnippet: "-- PG 13+: Publish partitioned table\nCREATE PUBLICATION part_pub\n  FOR TABLE orders  -- includes all partitions\n  WITH (publish_via_partition_root = true);\n\n-- Without publish_via_partition_root:\n-- Changes reference partition names, subscriber\n-- must have same partition names\n\n-- Subscriber can have different partitioning:\n-- Publisher: PARTITION BY RANGE (created_at)\n-- Subscriber: PARTITION BY HASH (id)\n-- Works with publish_via_partition_root = true\n\n-- Adding new partitions:\n-- Publisher: automatically included via parent\n-- Subscriber: add partition, then:\nALTER SUBSCRIPTION sub REFRESH PUBLICATION;", tags: ['admin', 'logical-replication', 'partitioning', 'pg13'] },
  { id: 'pg-admin-l4-049', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'How do you perform pg_basebackup from a standby server instead of the primary?', options: ['Backups can only be taken from the primary', 'pg_basebackup can target a standby server to offload backup I/O from the primary — connect to the standby with proper replication permissions; the backup will be consistent and usable for creating additional standbys or for PITR when combined with WAL from the primary', 'Standby backups are always inconsistent', 'Use pg_dump on standbys instead'], correctAnswer: 1, explanation: 'Taking backups from a standby reduces I/O load on the primary. The standby must have max_wal_senders configured. The backup is taken from the standby data files and is consistent. For PITR, you still need WAL from the primary archive. This pattern is common in production: primary → standby → backup.', codeSnippet: "-- On standby: allow replication connections\n-- postgresql.conf:\nmax_wal_senders = 5\n\n-- pg_hba.conf:\nhost replication backup_user 10.0.0.0/24 scram-sha-256\n\n-- Take backup from standby:\npg_basebackup -h standby_host -D /backup/data \\\n  -U backup_user -Fp -Xs -P\n\n-- For PITR recovery, you need the primary's WAL:\nrestore_command = 'cp /primary_archive/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\n\n-- Or create a cascading standby:\n-- Backup from standby → new standby\n-- Set primary_conninfo to point to the standby\n-- (cascading replication)", tags: ['admin', 'pg-basebackup', 'standby-backup', 'offload'] },
  { id: 'pg-admin-l4-050', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How do you detect and resolve table bloat caused by insufficient autovacuum?', options: ['Bloat does not affect PostgreSQL', 'Use pgstattuple extension or estimate bloat from pg_stat_user_tables (dead tuple ratio), then resolve with VACUUM FULL (exclusive lock, rewrites table), pg_repack (online, no lock), or CLUSTER — prevention is better via proper autovacuum tuning', 'Run REINDEX to fix bloat', 'DROP and recreate the table'], correctAnswer: 1, explanation: 'Table bloat occurs when dead tuples are not cleaned up fast enough. Detection: pgstattuple shows actual free space; pg_stat_user_tables shows dead tuple count; comparing pg_relation_size with estimated live data size reveals bloat. VACUUM FULL reclaims space but locks the table. pg_repack does it online without exclusive locks.', codeSnippet: "-- Detect bloat with pgstattuple:\nCREATE EXTENSION pgstattuple;\nSELECT * FROM pgstattuple('my_table');\n-- dead_tuple_percent > 20% indicates bloat\n\n-- Estimate bloat from stats:\nSELECT relname,\n  n_live_tup, n_dead_tup,\n  round(100.0 * n_dead_tup / NULLIF(n_live_tup + n_dead_tup, 0), 1)\n    AS dead_pct,\n  pg_size_pretty(pg_total_relation_size(relid)) AS size\nFROM pg_stat_user_tables\nWHERE n_dead_tup > 10000\nORDER BY n_dead_tup DESC;\n\n-- Fix: VACUUM FULL (locks table!)\nVACUUM FULL my_table;\n\n-- Fix: pg_repack (online, no lock)\npg_repack -d mydb -t my_table", tags: ['admin', 'autovacuum', 'bloat', 'pg-repack'] },
  { id: 'pg-admin-l4-051', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you use pg_stat_replication_slots to monitor logical replication slot performance?', options: ['This view does not exist', 'pg_stat_replication_slots (PG 14+) provides per-slot statistics including total bytes sent, number of transactions streamed/spilled to disk, and streaming vs spill counts — high spill counts indicate the subscriber cannot keep up and transactions are being written to disk', 'It only shows physical replication slots', 'Use pg_stat_subscription instead'], correctAnswer: 1, explanation: 'pg_stat_replication_slots shows logical slot activity: total_txns, total_bytes, stream_txns/bytes (PG 14+ in-progress streaming), spill_txns/bytes/count (when transaction exceeds logical_decoding_work_mem and spills to disk). High spill rates suggest increasing logical_decoding_work_mem or subscriber throughput.', codeSnippet: "-- Monitor logical replication slot stats (PG 14+):\nSELECT slot_name,\n  spill_txns, spill_count, spill_bytes,\n  stream_txns, stream_count, stream_bytes,\n  total_txns, total_bytes,\n  stats_reset\nFROM pg_stat_replication_slots;\n\n-- High spill_count: increase work mem\nALTER SYSTEM SET logical_decoding_work_mem = '256MB';\nSELECT pg_reload_conf();\n\n-- Reset statistics:\nSELECT pg_stat_reset_replication_slot('my_slot');\n\n-- PG 15+: check slot stats\nSELECT * FROM pg_stat_replication_slots\nWHERE slot_name = 'my_subscription';", tags: ['admin', 'replication-slots', 'pg-stat-replication-slots', 'pg14'] },
  { id: 'pg-admin-l4-052', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you test a PITR recovery procedure without affecting production?', options: ['PITR testing is not possible', 'Restore the base backup to a separate server/directory with a different port, configure restore_command and recovery target, start the instance, verify data integrity, then shut it down — automate this as a regular recovery drill to validate backup and archive integrity', 'Test on the production server during low traffic', 'Just trust that backups work'], correctAnswer: 1, explanation: 'Regular PITR testing is essential. Steps: (1) Restore base backup to a temp location, (2) Configure recovery with a separate port, (3) Set recovery_target_action = pause to inspect, (4) Run data verification queries, (5) Clean up. Automate this as a weekly/monthly cron job. Test both the backup and WAL archive integrity.', codeSnippet: "#!/bin/bash\n# Automated PITR recovery test\nRECOVERY_DIR=/tmp/pitr_test\nrm -rf $RECOVERY_DIR\n\n# Restore base backup\ntar xf /backup/base.tar -C $RECOVERY_DIR\n\n# Configure recovery\ncat >> $RECOVERY_DIR/postgresql.auto.conf <<EOF\nport = 5433\nrestore_command = 'cp /wal_archive/%f %p'\nrecovery_target_time = '$(date -d \"1 hour ago\" +\"%Y-%m-%d %H:%M:%S\")'\nrecovery_target_action = 'promote'\nEOF\n\ntouch $RECOVERY_DIR/recovery.signal\n\n# Start and verify\npg_ctl start -D $RECOVERY_DIR -w\npsql -p 5433 -c 'SELECT count(*) FROM critical_table;'\n\n# Cleanup\npg_ctl stop -D $RECOVERY_DIR\nrm -rf $RECOVERY_DIR", tags: ['admin', 'pitr', 'recovery-testing', 'automation'] },
  { id: 'pg-admin-l4-053', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Huge Pages', question: 'What is the impact of huge pages on PostgreSQL checkpoint performance?', options: ['No impact on checkpoints', 'Huge pages reduce the overhead of dirty page tracking and TLB misses during checkpoints — when shared_buffers is large, checkpoint writes benefit from reduced page table walks, and the OS can write dirty huge pages more efficiently in sequential I/O patterns', 'Huge pages slow down checkpoints', 'Checkpoints bypass page management entirely'], correctAnswer: 1, explanation: 'During checkpoints, PostgreSQL writes all dirty buffers to disk. With standard 4KB pages, this involves many TLB lookups. Huge pages reduce TLB pressure significantly. Additionally, the OS can track dirty state at the huge page granularity, reducing bookkeeping overhead. The impact is most noticeable with large shared_buffers (>16GB).', codeSnippet: "-- Checkpoint-related settings to tune alongside huge pages:\ncheckpoint_completion_target = 0.9  -- spread writes\ncheckpoint_timeout = '15min'  -- time between checkpoints\nmax_wal_size = '4GB'  -- WAL before forced checkpoint\n\n-- Monitor checkpoint performance:\nSELECT checkpoints_timed, checkpoints_req,\n  checkpoint_write_time, checkpoint_sync_time,\n  buffers_checkpoint, buffers_backend\nFROM pg_stat_bgwriter;\n\n-- High buffers_backend indicates shared_buffers\n-- pressure or checkpoint not keeping up\n\n-- With huge pages:\nhuge_pages = 'on'\nshared_buffers = '32GB'\n-- Reduces TLB misses during checkpoint writes", tags: ['admin', 'huge-pages', 'checkpoints', 'performance'] },
  { id: 'pg-admin-l4-054', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you handle sequences and identity columns in logical replication?', options: ['Sequences are automatically replicated', 'Logical replication does NOT replicate sequences — subscriber sequence values diverge from the publisher; solutions include periodically syncing sequences manually, using UUID primary keys instead, or setting subscriber sequences ahead of publisher values', 'Use ALTER SEQUENCE to sync', 'Sequences do not exist with logical replication'], correctAnswer: 1, explanation: 'Sequence values are local to each server. After initial sync, subscriber sequences reflect pre-sync state. If the subscriber is also writing data (bidirectional), sequence conflicts occur. Solutions: (1) Use UUIDs, (2) Use non-overlapping ranges (odd/even), (3) Periodically copy sequence values from publisher, (4) Use generated UUIDs.', codeSnippet: "-- Problem: subscriber sequence is out of sync\n\n-- Solution 1: Periodically sync sequences\n-- On publisher:\nSELECT 'SELECT setval(''' || sequencename || ''', ' ||\n  last_value || ');'\nFROM pg_sequences\nWHERE schemaname = 'public';\n-- Run output on subscriber\n\n-- Solution 2: Use UUIDs instead\nCREATE TABLE users (\n  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n  name TEXT\n);\n\n-- Solution 3: Non-overlapping ranges\n-- Publisher: START 1 INCREMENT 2 (odd)\n-- Subscriber: START 2 INCREMENT 2 (even)\nALTER SEQUENCE users_id_seq INCREMENT 2 RESTART 1;", tags: ['admin', 'logical-replication', 'sequences', 'identity'] },
  { id: 'pg-admin-l4-055', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'What is the --write-recovery-conf (-R) flag in pg_basebackup?', options: ['It writes a recovery test report', 'The -R flag automatically creates standby.signal file and writes primary_conninfo with the connection parameters used by pg_basebackup into postgresql.auto.conf — making the backup immediately usable as a streaming replication standby', 'It enables recovery mode in the backup', 'It writes backup metadata'], correctAnswer: 1, explanation: 'The -R flag saves significant manual configuration when setting up standbys. It creates standby.signal (which tells PostgreSQL to start in standby mode) and configures primary_conninfo (connection string to the primary) in postgresql.auto.conf. You just need to start the new instance and it begins replicating.', codeSnippet: "-- Create standby with -R:\npg_basebackup -h primary -D /standby/data \\\n  -U repl_user -Fp -Xs -P -R\n\n-- What -R creates:\n-- 1. /standby/data/standby.signal (empty file)\n-- 2. Appends to postgresql.auto.conf:\n--    primary_conninfo = 'user=repl_user host=primary\n--      port=5432 sslmode=prefer ...'\n\n-- Just start the standby:\npg_ctl start -D /standby/data\n\n-- Optionally add replication slot:\n-- On primary:\nSELECT pg_create_physical_replication_slot('standby1');\n-- Add to standby postgresql.auto.conf:\nprimary_slot_name = 'standby1'", tags: ['admin', 'pg-basebackup', 'standby-setup', 'recovery-conf'] },
  { id: 'pg-admin-l4-056', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'What is the emergency autovacuum mode and how does it differ from normal autovacuum?', options: ['Emergency mode uses VACUUM FULL', 'When a table nears the anti-wraparound threshold (autovacuum_freeze_max_age), emergency autovacuum runs with maximum aggression — it ignores cost_delay settings, cannot be cancelled, runs even if autovacuum is disabled on the table, and takes priority over other autovacuum work', 'Emergency mode sends alerts', 'It runs VACUUM on all tables simultaneously'], correctAnswer: 1, explanation: 'Emergency (anti-wraparound) autovacuum is a last-resort mechanism. It triggers when age(relfrozenxid) approaches autovacuum_freeze_max_age. It runs at full speed (no cost delay), cannot be cancelled, and ignores per-table autovacuum_enabled = false. Prevention through proper freeze tuning is far better than hitting emergency mode.', codeSnippet: "-- Check how close tables are to emergency vacuum:\nSELECT c.relname,\n  age(c.relfrozenxid) AS xid_age,\n  current_setting('autovacuum_freeze_max_age')::int\n    AS freeze_max_age,\n  round(100.0 * age(c.relfrozenxid) /\n    current_setting('autovacuum_freeze_max_age')::int, 1)\n    AS pct_to_emergency\nFROM pg_class c\nJOIN pg_namespace n ON c.relnamespace = n.oid\nWHERE c.relkind = 'r'\n  AND n.nspname NOT IN ('pg_catalog', 'information_schema')\nORDER BY age(c.relfrozenxid) DESC;\n\n-- Signs of emergency vacuum in logs:\n-- WARNING: oldest xmin is far in the past\n-- HINT: Close open transactions soon to avoid wraparound\n\n-- Prevention:\nALTER SYSTEM SET autovacuum_freeze_max_age = 200000000;", tags: ['admin', 'autovacuum', 'emergency', 'anti-wraparound'] },
  { id: 'pg-admin-l4-057', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you set up automated failover monitoring using replication statistics?', options: ['PostgreSQL handles failover automatically', 'Build monitoring that queries pg_stat_replication for missing standbys, excessive lag, and state changes — combine with tools like Patroni, repmgr, or pg_auto_failover that use these statistics to detect primary failure and trigger automated promotion', 'Use pg_stat_activity for failover', 'Failover monitoring requires third-party tools only'], correctAnswer: 1, explanation: 'Automated failover requires: (1) Health check of primary (pg_isready, connection test), (2) Lag monitoring via pg_stat_replication, (3) Standby health check, (4) Quorum/consensus to prevent split-brain, (5) Promotion. Tools like Patroni use etcd/ZooKeeper for consensus, repmgr uses shared state, pg_auto_failover uses a monitor node.', codeSnippet: "-- Key queries for failover monitoring:\n\n-- 1. Check all standbys are connected:\nSELECT count(*) AS connected_standbys\nFROM pg_stat_replication\nWHERE state = 'streaming';\n\n-- 2. Detect excessive lag:\nSELECT application_name,\n  pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn)\n    AS lag_bytes,\n  replay_lag\nFROM pg_stat_replication\nWHERE replay_lag > interval '30 seconds'\n  OR pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn)\n    > 1073741824;  -- 1GB\n\n-- 3. Patroni configuration example:\n-- bootstrap:\n--   dcs:\n--     ttl: 30\n--     loop_wait: 10\n--     maximum_lag_on_failover: 1048576", tags: ['admin', 'pg-stat-replication', 'failover', 'high-availability'] },
  { id: 'pg-admin-l4-058', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is timeline history and why does it matter for PITR?', options: ['Timelines are only used in time-travel queries', 'Each time a standby is promoted or PITR recovery finishes, a new timeline is created — timeline history files track these branching points, and recovery_target_timeline controls which timeline to follow during recovery (current, latest, or a specific ID)', 'Timelines are database schemas', 'Timeline is another name for WAL segment'], correctAnswer: 1, explanation: 'Timelines prevent WAL conflicts after promotion. When a standby promotes, it starts timeline N+1 and writes a timeline history file recording when the branch occurred. During PITR, recovery_target_timeline = latest follows the most recent timeline. This allows recovering from a backup taken before a failover and following the correct WAL sequence.', codeSnippet: "-- Check current timeline:\nSELECT pg_control_checkpoint();\n-- Shows timeline_id\n\n-- Timeline history files in pg_wal/:\n-- 00000002.history, 00000003.history, etc.\n-- Format: parent_timeline switch_point reason\n\n-- Recovery with timeline control:\nrestore_command = 'cp /archive/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_timeline = 'latest'  -- follow newest\n-- Or: recovery_target_timeline = 2  -- specific\n\n-- After promotion, new WAL files start with\n-- new timeline ID:\n-- 000000020000000000000001  -- timeline 2\n-- vs\n-- 000000010000000000000001  -- timeline 1", tags: ['admin', 'pitr', 'timeline', 'wal-history'] },
  { id: 'pg-admin-l4-059', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'How do you handle logical replication slots and subscriptions during pg_upgrade?', options: ['They are preserved automatically', 'pg_upgrade (PG 17+) can preserve logical replication slots; in earlier versions, slots and subscriptions must be dropped before upgrade and recreated after — failure to drop slots causes pg_upgrade to fail; subscriptions on the subscriber side must also be recreated', 'Logical replication is incompatible with pg_upgrade', 'Use pg_dump to preserve them'], correctAnswer: 1, explanation: 'Before PG 17, pg_upgrade requires dropping all logical replication slots (they cannot be transferred). On the publisher: drop publications and slots. On the subscriber: drop subscriptions. After upgrade, recreate everything and perform initial sync. PG 17 added support for preserving logical replication slots during pg_upgrade.', codeSnippet: "-- Pre-PG 17: Before upgrade on PUBLISHER:\nSELECT pg_drop_replication_slot(slot_name)\nFROM pg_replication_slots\nWHERE slot_type = 'logical';\nDROP PUBLICATION my_pub;\n\n-- Before upgrade on SUBSCRIBER:\nDROP SUBSCRIPTION my_sub;\n\n-- After upgrade, recreate:\n-- Publisher:\nCREATE PUBLICATION my_pub FOR ALL TABLES;\n\n-- Subscriber:\nCREATE SUBSCRIPTION my_sub\n  CONNECTION '...'\n  PUBLICATION my_pub;\n  -- Initial sync will re-copy data\n\n-- PG 17+: slots are preserved\npg_upgrade ...  -- slots survive the upgrade", tags: ['admin', 'pg-upgrade', 'logical-replication', 'slots'] },
  { id: 'pg-admin-l4-060', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'What is the disable_on_error subscription parameter and when should you use it?', options: ['It disables error logging', 'disable_on_error (PG 15+) automatically disables the subscription when an apply error occurs instead of retrying indefinitely — this prevents the apply worker from consuming resources on unresolvable conflicts and allows administrators to investigate and fix the issue', 'It disables the publisher on error', 'It ignores all errors'], correctAnswer: 1, explanation: 'Without disable_on_error, the apply worker retries failed transactions in a loop, consuming CPU and generating log spam. With disable_on_error = true, the subscription stops after the first error, preserving the error context for diagnosis. After fixing the issue, re-enable with ALTER SUBSCRIPTION ... ENABLE.', codeSnippet: "-- Create subscription that stops on error:\nCREATE SUBSCRIPTION my_sub\n  CONNECTION 'host=pub dbname=mydb user=repl'\n  PUBLICATION my_pub\n  WITH (disable_on_error = true);\n\n-- After error, subscription is disabled:\n-- Check status:\nSELECT subname, subenabled, subslotname\nFROM pg_subscription;\n\n-- Check what went wrong:\nSELECT * FROM pg_stat_subscription\nWHERE subname = 'my_sub';\n-- Also check server logs for detailed error\n\n-- Fix the conflict, then re-enable:\nALTER SUBSCRIPTION my_sub ENABLE;", tags: ['admin', 'logical-replication', 'error-handling', 'pg15'] },
  { id: 'pg-admin-l4-061', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'How do you take a backup with pg_basebackup using a replication slot to prevent WAL removal?', options: ['Replication slots are not needed for backups', 'Use --slot (-S) to specify a replication slot that prevents WAL cleanup during backup, and --create-slot (-C) to create it automatically — this is critical for long-running backups where WAL might otherwise be recycled before the backup completes', 'WAL is never removed during backup', 'Use archive_command instead'], correctAnswer: 1, explanation: 'Without a replication slot, WAL segments might be removed during a long backup (especially with low wal_keep_size). A temporary replication slot (-S with --create-slot) guarantees WAL retention during backup. Permanent slots can be reused but must be manually managed. The slot is dropped if --create-slot is used with a non-permanent slot.', codeSnippet: "-- Create and use a temporary slot:\npg_basebackup -h primary -D /backup/data \\\n  -U repl_user -Fp -Xs -P \\\n  --slot=backup_slot --create-slot\n  -- Slot is created before backup, dropped after\n\n-- Use existing permanent slot:\nSELECT pg_create_physical_replication_slot(\n  'backup_slot', true\n);\npg_basebackup -D /backup/data \\\n  -S backup_slot -Xs -P\n\n-- Verify slot exists:\nSELECT slot_name, active,\n  pg_size_pretty(\n    pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)\n  ) AS retained_wal\nFROM pg_replication_slots\nWHERE slot_name = 'backup_slot';", tags: ['admin', 'pg-basebackup', 'replication-slot', 'wal-retention'] },
  { id: 'pg-admin-l4-062', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How do you configure autovacuum differently for TOAST tables?', options: ['TOAST tables do not need vacuuming', 'TOAST tables have separate autovacuum settings that can be configured via ALTER TABLE on the main table with toast. prefix — TOAST tables need vacuum for dead tuple cleanup but their optimal settings often differ from the main table due to different update patterns', 'TOAST tables share main table settings', 'Use ALTER TOAST TABLE syntax'], correctAnswer: 1, explanation: 'TOAST tables store large values out-of-line. They accumulate dead tuples independently of the main table (especially with large column updates). PG 14+ allows setting TOAST-specific autovacuum parameters. Before that, TOAST tables inherit the main table settings. Monitor TOAST bloat separately as it can grow significantly.', codeSnippet: "-- PG 14+: Set TOAST-specific autovacuum:\nALTER TABLE my_table SET (\n  toast.autovacuum_vacuum_scale_factor = 0.05,\n  toast.autovacuum_vacuum_threshold = 100,\n  toast.autovacuum_vacuum_cost_delay = 0\n);\n\n-- Find TOAST table for a table:\nSELECT c.relname AS main_table,\n  t.relname AS toast_table,\n  pg_size_pretty(pg_relation_size(t.oid)) AS toast_size\nFROM pg_class c\nJOIN pg_class t ON t.oid = c.reltoastrelid\nWHERE c.relname = 'my_table';\n\n-- Check TOAST bloat:\nSELECT relname,\n  n_dead_tup, n_live_tup,\n  last_autovacuum\nFROM pg_stat_all_tables\nWHERE relname LIKE 'pg_toast_%'\nORDER BY n_dead_tup DESC LIMIT 10;", tags: ['admin', 'autovacuum', 'toast', 'pg14'] },
  { id: 'pg-admin-l4-063', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you monitor synchronous replication quorum status?', options: ['Synchronous replication has no quorum', 'Check pg_stat_replication.sync_state for each standby (sync, async, potential, quorum) and verify synchronous_standby_names configuration — sync indicates the standby is the current synchronous target, quorum means it participates in FIRST N or ANY N quorum decisions', 'Use pg_stat_database instead', 'Quorum is managed externally only'], correctAnswer: 1, explanation: 'sync_state values: async (not synchronous), potential (candidate but not active sync), sync (current synchronous standby in FIRST mode), quorum (participates in ANY N quorum). FIRST N prioritizes by order in the list; ANY N requires N of the listed standbys to confirm. Monitor to ensure enough sync standbys are connected.', codeSnippet: "-- Configure quorum-based synchronous replication:\n-- postgresql.conf:\nsynchronous_standby_names = 'ANY 2 (s1, s2, s3)'\n-- Any 2 of 3 must confirm before commit returns\n\n-- Or priority-based:\nsynchronous_standby_names = 'FIRST 2 (s1, s2, s3)'\n-- First 2 in order must confirm\n\n-- Monitor sync status:\nSELECT application_name, client_addr,\n  sync_state,  -- sync/async/potential/quorum\n  sync_priority,\n  pg_wal_lsn_diff(sent_lsn, flush_lsn) AS pending\nFROM pg_stat_replication\nORDER BY sync_priority;\n\nSHOW synchronous_standby_names;\nSHOW synchronous_commit;", tags: ['admin', 'pg-stat-replication', 'synchronous', 'quorum'] },
  { id: 'pg-admin-l4-064', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is the role of backup_label and backup_manifest files in PITR?', options: ['They are documentation files', 'backup_label (created during pg_basebackup) records the backup start LSN and checkpoint location needed to begin WAL replay; backup_manifest (PG 13+) contains checksums and file sizes for backup verification with pg_verifybackup — both are critical for reliable recovery', 'They control PostgreSQL configuration', 'They are only used by pg_dump'], correctAnswer: 1, explanation: 'backup_label tells PostgreSQL where to start WAL replay during recovery (the checkpoint from which the backup was taken). Without it, PostgreSQL does not know the backup is a base backup. backup_manifest enables post-backup verification. Corrupted or missing backup_label prevents recovery from succeeding.', codeSnippet: "-- backup_label contents (auto-generated):\n-- START WAL LOCATION: 0/2000028\n-- CHECKPOINT LOCATION: 0/2000060\n-- BACKUP METHOD: streamed\n-- BACKUP FROM: primary\n-- START TIME: 2024-06-15 10:00:00 UTC\n-- LABEL: pg_basebackup base backup\n-- START TIMELINE: 1\n\n-- backup_manifest (PG 13+):\n-- JSON file containing:\n-- - Files with size, checksum (CRC32C)\n-- - WAL ranges needed for recovery\n-- - Manifest checksum\n\n-- Verify manifest:\npg_verifybackup /backup/data\n\n-- During recovery, PostgreSQL reads backup_label\n-- to determine the WAL replay start point", tags: ['admin', 'pitr', 'backup-label', 'backup-manifest'] },
  { id: 'pg-admin-l4-065', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you use logical replication to migrate data between different table structures?', options: ['Tables must have identical structures', 'Logical replication allows different table structures on publisher and subscriber as long as column names and types match for replicated columns — the subscriber can have additional columns (filled with defaults), different indexes, different constraints, or different storage parameters', 'Use pg_dump for structure changes', 'ALTER TABLE on both sides simultaneously'], correctAnswer: 1, explanation: 'Logical replication matches columns by name, not position. The subscriber table can have: extra columns (with defaults/nullable), different indexes, different CHECK constraints, different tablespaces, different partitioning schemes, and column reordering. This flexibility enables gradual schema evolution and migration strategies.', codeSnippet: "-- Publisher table:\nCREATE TABLE users (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  email TEXT\n);\n\n-- Subscriber table (different structure):\nCREATE TABLE users (\n  id INTEGER PRIMARY KEY,\n  name TEXT,\n  email TEXT,\n  -- Extra columns (filled with defaults):\n  migrated_at TIMESTAMPTZ DEFAULT now(),\n  source TEXT DEFAULT 'legacy',\n  -- Different index:\n  CONSTRAINT email_unique UNIQUE (email)\n);\n\n-- Column list publication (PG 15+):\nCREATE PUBLICATION user_pub\n  FOR TABLE users (id, name, email);\n-- Only specified columns are replicated", tags: ['admin', 'logical-replication', 'schema-migration', 'flexibility'] },
  { id: 'pg-admin-l4-066', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'What is the --clone option in pg_upgrade (PG 17+) and how does it compare to --link?', options: ['Clone and link are identical', 'The --clone option uses filesystem reflinks (copy-on-write) to create instant copies that are independent of the original — unlike --link which shares physical blocks (making the old cluster unusable after new cluster writes), --clone preserves the old cluster as a safe rollback', 'Clone creates a full copy like default mode', 'Clone only works with ZFS'], correctAnswer: 1, explanation: 'Reflinks (supported on XFS, Btrfs, APFS, ZFS) create instant copies where blocks are shared until one side modifies them (copy-on-write). This gives the speed of --link (near-instant) with the safety of copy mode (old cluster remains usable for rollback). Check filesystem support with test reflinks before relying on this.', codeSnippet: "-- Clone mode (PG 17+, requires reflink support):\npg_upgrade \\\n  --old-datadir=/pg16/data \\\n  --new-datadir=/pg17/data \\\n  --old-bindir=/pg16/bin \\\n  --new-bindir=/pg17/bin \\\n  --clone\n\n-- Comparison:\n-- Default (copy): slow, safe, 2x disk space\n-- --link:  fast, old cluster unusable after writes\n-- --clone: fast, old cluster preserved (safe rollback)\n\n-- Check reflink support:\ncp --reflink=always testfile testfile2\n-- If it works, your filesystem supports reflinks\n\n-- Supported filesystems:\n-- Linux: XFS, Btrfs, OCFS2, ext4 (kernel 6.x+)\n-- macOS: APFS\n-- Solaris: ZFS", tags: ['admin', 'pg-upgrade', 'clone', 'reflink', 'pg17'] },
  { id: 'pg-admin-l4-067', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How do you handle autovacuum for tables with billions of rows?', options: ['Use the same settings as small tables', 'For very large tables, use aggressive per-table settings (very low scale_factor, high cost_limit), consider partitioning to keep individual partitions manageable, and monitor vacuum duration — partitioned tables allow parallel vacuum across partitions and faster individual vacuums', 'Disable autovacuum and vacuum manually', 'Large tables do not need vacuuming'], correctAnswer: 1, explanation: 'A 1-billion row table with default 20% scale_factor needs 200M dead tuples before vacuum triggers. Reduce scale_factor to 0.01 (triggers at 10M dead tuples). Partitioning is the best strategy: smaller partitions vacuum independently, in parallel, and complete faster. Time-based partitioning allows dropping old partitions instead of vacuuming.', codeSnippet: "-- Per-table aggressive settings for huge tables:\nALTER TABLE huge_events SET (\n  autovacuum_vacuum_scale_factor = 0.001,\n  autovacuum_vacuum_threshold = 10000,\n  autovacuum_vacuum_cost_delay = 0,\n  autovacuum_vacuum_cost_limit = 5000,\n  autovacuum_freeze_min_age = 10000000\n);\n\n-- Better: partition the table\nCREATE TABLE events (\n  id BIGINT GENERATED ALWAYS AS IDENTITY,\n  created_at TIMESTAMPTZ NOT NULL,\n  data JSONB\n) PARTITION BY RANGE (created_at);\n\n-- Each partition is vacuumed independently\n-- Old partitions can be dropped:\nDROP TABLE events_2023_01;  -- instant, no vacuum\n\n-- Monitor vacuum duration:\nSELECT relname, last_autovacuum,\n  last_autovacuum - lag(last_autovacuum)\n    OVER (ORDER BY last_autovacuum) AS vacuum_interval\nFROM pg_stat_user_tables\nWHERE relname = 'huge_events';", tags: ['admin', 'autovacuum', 'large-tables', 'partitioning'] },
  { id: 'pg-admin-l4-068', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you detect and troubleshoot replication slots that are preventing WAL cleanup?', options: ['Replication slots never cause WAL issues', 'Monitor pg_replication_slots for inactive slots with large retained WAL, check wal_status column (PG 13+) for slots marked as lost, and compare restart_lsn with current WAL position — use max_slot_wal_keep_size to automatically invalidate slots that retain too much WAL', 'Use pg_stat_bgwriter to detect WAL issues', 'Only logical slots cause WAL retention'], correctAnswer: 1, explanation: 'Both physical and logical replication slots retain WAL from their restart_lsn. Inactive slots are the biggest risk. PG 13+ wal_status column shows: reserved (within wal_keep_size), extended (beyond wal_keep_size but within max_slot_wal_keep_size), unreserved (may be removed), lost (invalidated). Regular monitoring prevents disk-full emergencies.', codeSnippet: "-- Comprehensive slot monitoring:\nSELECT slot_name, slot_type, active,\n  pg_size_pretty(\n    pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)\n  ) AS retained_wal,\n  wal_status,  -- PG 13+\n  safe_wal_size,  -- PG 13+\n  CASE\n    WHEN NOT active AND\n      pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)\n      > 5368709120 THEN 'CRITICAL: >5GB retained'\n    WHEN NOT active THEN 'WARNING: inactive slot'\n    ELSE 'OK'\n  END AS alert\nFROM pg_replication_slots\nORDER BY\n  pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) DESC;\n\n-- Set WAL retention limit:\nALTER SYSTEM SET max_slot_wal_keep_size = '10GB';", tags: ['admin', 'replication-slots', 'wal-cleanup', 'troubleshooting'] },
  { id: 'pg-admin-l4-069', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Huge Pages', question: 'How do you configure huge pages for PostgreSQL on NUMA systems?', options: ['NUMA has no effect on huge pages', 'On NUMA systems, huge pages should be distributed across NUMA nodes matching PostgreSQL process affinity — use numactl to bind PostgreSQL to specific nodes and allocate huge pages per-node to avoid remote memory access latency penalties', 'NUMA is only relevant for Oracle', 'Huge pages are always NUMA-aware'], correctAnswer: 1, explanation: 'NUMA (Non-Uniform Memory Access) means memory access latency depends on which CPU/node the memory belongs to. Allocating huge pages on all NUMA nodes and binding PostgreSQL to specific nodes ensures memory locality. Remote NUMA access can be 1.5-2x slower. Use numactl --interleave for balanced allocation across nodes.', codeSnippet: "-- Check NUMA topology:\nnumactl --hardware\n# node 0: 128GB, node 1: 128GB\n\n-- Allocate huge pages per NUMA node:\necho 8192 > /sys/devices/system/node/node0/hugepages/hugepages-2048kB/nr_hugepages\necho 8192 > /sys/devices/system/node/node1/hugepages/hugepages-2048kB/nr_hugepages\n\n-- Start PostgreSQL with NUMA interleaving:\nnumactl --interleave=all pg_ctl start -D /pgdata\n\n-- Or bind to specific node:\nnumactl --cpunodebind=0 --membind=0 pg_ctl start -D /pgdata\n\n-- Verify NUMA allocation:\nnumastat -p $(head -1 /pgdata/postmaster.pid)\n\n-- PostgreSQL config:\nhuge_pages = 'on'\nshared_buffers = '128GB'", tags: ['admin', 'huge-pages', 'numa', 'memory-optimization'] },
  { id: 'pg-admin-l4-070', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you set up WAL archiving to cloud storage (S3, GCS, Azure)?', options: ['Cloud archiving requires commercial tools', 'Use tools like pgBackRest, WAL-G, or barman that support cloud storage natively — they handle compression, encryption, parallel upload, and WAL management; alternatively, use archive_command with cloud CLI tools like aws s3 cp or gsutil cp', 'Use archive_command with NFS only', 'WAL cannot be archived to cloud storage'], correctAnswer: 1, explanation: 'Modern backup tools support cloud storage natively: pgBackRest (S3, GCS, Azure with parallel upload, encryption, differential backups), WAL-G (S3, GCS, Azure, Swift with delta backups, LZ4/zstd compression), barman (S3 with barman-cloud). For simple setups, archive_command with cloud CLI works but lacks advanced features.', codeSnippet: "-- Method 1: pgBackRest with S3\n# pgbackrest.conf:\n[global]\nrepo1-type=s3\nrepo1-s3-bucket=pg-backups\nrepo1-s3-region=us-east-1\nrepo1-s3-endpoint=s3.amazonaws.com\nrepo1-cipher-type=aes-256-cbc\n\n# postgresql.conf:\narchive_command = 'pgbackrest --stanza=main archive-push %p'\nrestore_command = 'pgbackrest --stanza=main archive-get %f \"%p\"'\n\n-- Method 2: WAL-G with S3\n# export WALG_S3_PREFIX=s3://pg-backups/wal\narchive_command = 'wal-g wal-push %p'\nrestore_command = 'wal-g wal-fetch %f %p'\n\n-- Method 3: Direct S3 (simple but limited)\narchive_command = 'aws s3 cp %p s3://bucket/wal/%f'", tags: ['admin', 'pitr', 'cloud-storage', 'wal-archiving'] },
  { id: 'pg-admin-l4-071', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'How do you upgrade PostgreSQL extensions that use C code or shared libraries?', options: ['Extensions upgrade automatically', 'Install the extension packages compiled for the new PostgreSQL version before pg_upgrade, ensure .so files are in the new lib directory, and run ALTER EXTENSION ... UPDATE after upgrade — some extensions may require special migration steps or are incompatible with certain versions', 'Recompile all extensions from source', 'C extensions cannot be upgraded'], correctAnswer: 1, explanation: 'C extensions (.so files) are compiled against a specific PostgreSQL major version. The new version needs matching .so files. Package managers usually provide versioned packages (e.g., postgresql-16-postgis-3). After pg_upgrade, ALTER EXTENSION UPDATE runs migration scripts to update catalog entries and functions.', codeSnippet: "-- Before upgrade: check extensions\nSELECT e.extname, e.extversion,\n  a.default_version AS available_version\nFROM pg_extension e\nLEFT JOIN pg_available_extensions a\n  ON e.extname = a.name;\n\n-- Install packages for new PG version:\nsudo apt install \\\n  postgresql-16-postgis-3 \\\n  postgresql-16-pg-stat-statements \\\n  postgresql-16-pgvector\n\n-- After pg_upgrade:\nALTER EXTENSION postgis UPDATE;\nALTER EXTENSION pg_stat_statements UPDATE;\nALTER EXTENSION vector UPDATE;\n\n-- For custom-compiled extensions:\ncd /path/to/extension/source\nmake clean\nPG_CONFIG=/usr/lib/postgresql/16/bin/pg_config make\nsudo make install", tags: ['admin', 'pg-upgrade', 'extensions', 'shared-libraries'] },
  { id: 'pg-admin-l4-072', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'What is the streaming option for logical replication subscriptions and why is it important?', options: ['It enables WAL streaming', 'The streaming option (PG 14+) allows subscribers to apply large in-progress transactions as they stream rather than waiting for commit — this reduces memory usage and apply latency for large transactions that would otherwise accumulate in logical_decoding_work_mem and spill to disk', 'It streams query results to subscribers', 'It controls the network protocol'], correctAnswer: 1, explanation: 'Without streaming, the subscriber buffers the entire transaction in memory (or spills to disk) until COMMIT. With streaming = on, the subscriber applies changes as they arrive, using a temporary table for uncommitted changes that get committed or rolled back when the transaction completes. PG 16 added streaming = parallel for parallel apply.', codeSnippet: "-- PG 14+: Enable streaming\nCREATE SUBSCRIPTION my_sub\n  CONNECTION 'host=pub dbname=mydb user=repl'\n  PUBLICATION my_pub\n  WITH (streaming = on);\n\n-- PG 16+: Parallel streaming\nCREATE SUBSCRIPTION my_sub\n  CONNECTION '...'\n  PUBLICATION my_pub\n  WITH (streaming = parallel);\n\n-- Without streaming, large txns spill to disk\n-- when exceeding logical_decoding_work_mem\nSHOW logical_decoding_work_mem;  -- default 64MB\n\n-- Increase if streaming not available:\nALTER SYSTEM SET logical_decoding_work_mem = '256MB';\n\n-- Monitor spill stats (PG 14+):\nSELECT * FROM pg_stat_replication_slots;", tags: ['admin', 'logical-replication', 'streaming', 'large-transactions'] },
  { id: 'pg-admin-l4-073', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'How do you use pg_basebackup with target = blackhole for backup testing?', options: ['Blackhole is a network protocol', 'PG 15+ supports --target=blackhole which performs all backup operations (reading files, checkpointing, WAL streaming) without writing data — useful for testing backup performance, verifying backup capability, and measuring I/O impact on the primary without needing storage', 'It deletes old backups', 'It backs up to /dev/null'], correctAnswer: 1, explanation: 'The blackhole target runs the full backup process (checkpoint, file streaming, WAL streaming) but discards the data. This is useful for: testing backup speed without storage, measuring I/O impact on production, validating replication user permissions, and testing network throughput. Requires PG 15+ on the server side.', codeSnippet: "-- Test backup performance without storage (PG 15+):\npg_basebackup -h primary \\\n  --target=blackhole \\\n  -U repl_user -Xs -P -v\n\n-- Output shows:\n-- Throughput: xxx MB/s\n-- Total data: xxx MB\n-- No files written\n\n-- Other target options (PG 15+):\n-- --target=server:/path  (backup to server's filesystem)\n-- --target=blackhole  (discard data)\n\n-- Traditional way to measure backup speed:\ntime pg_basebackup -D /dev/null -Ft -Xs 2>/dev/null\n-- Note: -Ft to /dev/null doesn't work on all OS\n\n-- Use for regular backup capability testing:\n# cron: pg_basebackup --target=blackhole ...\n# Alert if non-zero exit code", tags: ['admin', 'pg-basebackup', 'testing', 'blackhole', 'pg15'] },
  { id: 'pg-admin-l4-074', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How does vacuum_failsafe_age (PG 14+) protect against transaction ID wraparound?', options: ['It sets the maximum database age', 'vacuum_failsafe_age (default 1.6 billion) is a last-resort trigger that disables vacuum cost-based delay and index cleanup when a table XID age reaches this threshold — this makes vacuum run at maximum speed to prevent the catastrophic 2-billion XID wraparound shutdown', 'It controls when pg_upgrade runs', 'It limits connection age'], correctAnswer: 1, explanation: 'vacuum_failsafe_age is a safety net added in PG 14. When triggered, vacuum: (1) disables cost-based delay (runs full speed), (2) skips index vacuuming (only freezes tuples), (3) skips truncation. This is more aggressive than anti-wraparound vacuum and sacrifices index cleanup for raw freezing speed. It is the last defense before database shutdown.', codeSnippet: "-- Check vacuum_failsafe_age (PG 14+):\nSHOW vacuum_failsafe_age;  -- default: 1600000000\n\n-- Thresholds in order:\n-- vacuum_freeze_min_age:      50,000,000  (normal freeze)\n-- autovacuum_freeze_max_age: 200,000,000  (anti-wraparound)\n-- vacuum_failsafe_age:     1,600,000,000  (failsafe)\n-- Hard limit:              2,147,483,647  (shutdown)\n\n-- Monitor proximity to failsafe:\nSELECT relname,\n  age(relfrozenxid) AS xid_age,\n  CASE\n    WHEN age(relfrozenxid) > 1600000000 THEN 'FAILSAFE'\n    WHEN age(relfrozenxid) > 200000000 THEN 'WRAPAROUND'\n    ELSE 'NORMAL'\n  END AS vacuum_mode\nFROM pg_class\nWHERE relkind = 'r'\nORDER BY age(relfrozenxid) DESC LIMIT 10;", tags: ['admin', 'autovacuum', 'failsafe', 'xid-wraparound', 'pg14'] },
  { id: 'pg-admin-l4-075', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you detect split-brain scenarios in a PostgreSQL replication cluster?', options: ['Split-brain cannot occur with PostgreSQL', 'Monitor for multiple servers accepting writes by checking pg_is_in_recovery() on all nodes, verify only one server has recovery = false, and use fencing mechanisms — split-brain occurs when a former primary comes back up writable after a standby was promoted', 'Use pg_stat_database to detect split-brain', 'PostgreSQL prevents split-brain automatically'], correctAnswer: 1, explanation: 'Split-brain occurs when two servers both accept writes, causing data divergence. Prevention: (1) Fence the old primary before promotion (STONITH), (2) Use pg_is_in_recovery() health checks, (3) HA tools like Patroni with DCS (etcd) consensus, (4) Verify timeline IDs match. Recovery requires manual data reconciliation or choosing one timeline.', codeSnippet: "-- Check if server is primary or standby:\nSELECT pg_is_in_recovery();\n-- false = primary (accepts writes)\n-- true = standby (read-only)\n\n-- Health check script:\n#!/bin/bash\nfor host in primary standby1 standby2; do\n  result=$(psql -h $host -tAc 'SELECT pg_is_in_recovery()')\n  echo \"$host: recovery=$result\"\n  if [ \"$result\" = \"f\" ]; then\n    echo \"$host is writable (primary)\"\n    PRIMARIES=$((PRIMARIES + 1))\n  fi\ndone\n\nif [ $PRIMARIES -gt 1 ]; then\n  echo 'ALERT: SPLIT BRAIN DETECTED!'\n  # Fence one of the primaries immediately\nfi\n\n-- Check timeline (diverged = split brain):\nSELECT timeline_id FROM pg_control_checkpoint();", tags: ['admin', 'pg-stat-replication', 'split-brain', 'high-availability'] },
  { id: 'pg-admin-l4-076', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you monitor and tune the apply worker performance in logical replication?', options: ['Apply workers cannot be tuned', 'Monitor pg_stat_subscription for apply worker activity, check for apply lag using latest_end_lsn, tune max_logical_replication_workers and max_sync_workers_per_subscription, and ensure the subscriber has sufficient resources (CPU, I/O, memory) for applying changes', 'Use pg_stat_activity only', 'Increase shared_buffers on subscriber'], correctAnswer: 1, explanation: 'Apply worker performance depends on: subscriber disk I/O (index maintenance for applied changes), CPU (decoding and applying), memory (logical_decoding_work_mem), and parallelism (PG 16+ parallel apply). Monitor pg_stat_subscription for lag. Bottlenecks are usually subscriber index maintenance or constraint checking on the applied data.', codeSnippet: "-- Monitor apply workers:\nSELECT subname, pid, relid::regclass,\n  received_lsn, last_msg_send_time,\n  last_msg_receipt_time, latest_end_lsn\nFROM pg_stat_subscription;\n\n-- Tune worker counts:\nALTER SYSTEM SET max_logical_replication_workers = 8;\nALTER SYSTEM SET max_sync_workers_per_subscription = 4;\nALTER SYSTEM SET max_worker_processes = 16;\n\n-- Check apply worker activity:\nSELECT pid, wait_event_type, wait_event, state, query\nFROM pg_stat_activity\nWHERE backend_type = 'logical replication worker';\n\n-- PG 16+: parallel apply\nALTER SUBSCRIPTION my_sub SET (streaming = parallel);\n-- Multiple workers apply changes concurrently", tags: ['admin', 'logical-replication', 'apply-worker', 'performance-tuning'] },
  { id: 'pg-admin-l4-077', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_basebackup', question: 'How do you use pg_basebackup with data checksums and verify backup integrity?', options: ['Checksums are not related to backups', 'When data checksums are enabled on the server (initdb --data-checksums), pg_basebackup verifies page checksums during transfer and backup_manifest includes checksums — combine with pg_verifybackup for end-to-end verification from source through storage', 'Checksums only work for WAL files', 'Use md5sum on backup files'], correctAnswer: 1, explanation: 'Data checksums (enabled at initdb or via pg_checksums) protect against storage corruption. During pg_basebackup, pages are verified against their checksums as they are read. The backup_manifest provides CRC32C checksums for all files. pg_verifybackup validates the manifest. This creates a chain of verification from source disk through backup storage.', codeSnippet: "-- Check if checksums are enabled:\nSHOW data_checksums;  -- on/off\n\n-- Enable checksums on existing cluster (PG 12+):\npg_checksums --enable -D /pgdata\n-- Requires server to be stopped\n\n-- pg_basebackup with checksum verification:\npg_basebackup -D /backup/data -Fp -Xs -P \\\n  --no-verify-checksums  -- skip (NOT recommended)\n  -- Default: verify checksums if enabled\n\n-- Verify backup integrity:\npg_verifybackup /backup/data\n\n-- Check for corruption in live database:\nSELECT datname,\n  checksum_failures, checksum_last_failure\nFROM pg_stat_database\nWHERE checksum_failures > 0;", tags: ['admin', 'pg-basebackup', 'checksums', 'data-integrity'] },
  { id: 'pg-admin-l4-078', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you perform PITR for a single database in a multi-database cluster?', options: ['Use recovery_target_database parameter', 'PostgreSQL PITR is cluster-wide — you cannot recover a single database independently; workarounds include: restoring the full cluster and using pg_dump to extract the desired database state, or using logical replication/pg_dump for per-database backup strategies', 'Set restore_database in recovery config', 'Use pg_restore with a timestamp'], correctAnswer: 1, explanation: 'PITR operates at the cluster level because WAL contains changes for all databases. To get per-database point-in-time recovery: (1) Restore the entire cluster to a temporary instance at the desired time, (2) pg_dump the specific database from the temporary instance, (3) pg_restore into production. For per-database backup, use logical backup (pg_dump) with scheduled snapshots.', codeSnippet: "-- Step 1: Full cluster PITR to temp instance\n# Restore base backup to /tmp/pitr_recovery\nrestore_command = 'cp /archive/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\n\n-- Start on different port\nport = 5433\nrecovery_target_action = 'promote'\n\n-- Step 2: Extract the specific database\npg_dump -h localhost -p 5433 -d target_db \\\n  -Fc -f /tmp/target_db_pitr.dump\n\n-- Step 3: Restore to production\npg_restore -d target_db_restored \\\n  /tmp/target_db_pitr.dump\n\n-- Alternative: per-database logical backup schedule\n# Cron: pg_dump -d mydb -Fc > /backup/mydb_$(date).dump\n-- Provides per-database point-in-time snapshots", tags: ['admin', 'pitr', 'single-database', 'recovery-strategy'] },
  { id: 'pg-admin-l4-079', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Autovacuum Tuning', question: 'How do you prevent autovacuum from interfering with peak production hours?', options: ['Schedule autovacuum to run only at night', 'Autovacuum cannot be scheduled directly, but you can reduce its aggressiveness during peak hours by dynamically adjusting cost_delay and cost_limit with ALTER SYSTEM + pg_reload_conf, or use per-table settings to prioritize critical tables while throttling others', 'Disable autovacuum during business hours', 'Use pg_cron to control vacuum'], correctAnswer: 1, explanation: 'Completely disabling autovacuum risks bloat and wraparound. Instead: (1) Increase cost_delay during peak hours (slower vacuum, less I/O impact), (2) Decrease during off-peak (catch up on maintenance), (3) Use per-table settings for critical tables. Scripts can be scheduled via pg_cron or OS cron to dynamically adjust these parameters.', codeSnippet: "-- Scheduled vacuum throttling with pg_cron:\n\n-- Peak hours: throttle autovacuum\nSELECT cron.schedule('peak_start', '0 8 * * 1-5',\n  $$ALTER SYSTEM SET autovacuum_vacuum_cost_delay = 20;\n    SELECT pg_reload_conf()$$\n);\n\n-- Off-peak: aggressive autovacuum\nSELECT cron.schedule('peak_end', '0 20 * * 1-5',\n  $$ALTER SYSTEM SET autovacuum_vacuum_cost_delay = 0;\n    SELECT pg_reload_conf()$$\n);\n\n-- Per-table: always keep critical tables clean\nALTER TABLE critical_table SET (\n  autovacuum_vacuum_cost_delay = 0,  -- always fast\n  autovacuum_vacuum_cost_limit = 2000\n);\n\n-- Monitor impact:\nSELECT * FROM pg_stat_progress_vacuum;", tags: ['admin', 'autovacuum', 'scheduling', 'performance-management'] },
  { id: 'pg-admin-l4-080', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'How do you handle custom configuration files (postgresql.conf, pg_hba.conf) during pg_upgrade?', options: ['Configuration files are automatically migrated', 'pg_upgrade does NOT migrate configuration files — you must manually copy and merge settings from the old cluster configuration, adjusting for new defaults, deprecated parameters, and renamed settings in the new version before starting the upgraded cluster', 'pg_upgrade converts settings automatically', 'Use ALTER SYSTEM to preserve settings'], correctAnswer: 1, explanation: 'pg_upgrade creates a fresh configuration in the new cluster. Your custom settings (tuning, authentication, connection limits) must be manually transferred. Some parameters are renamed, removed, or have changed defaults between versions. Review release notes for configuration changes. postgresql.auto.conf settings are also not transferred.', codeSnippet: "-- Before upgrade: document current config\n-- Save non-default settings:\nSELECT name, setting, source\nFROM pg_settings\nWHERE source NOT IN ('default', 'override')\nORDER BY source, name;\n\n-- After pg_upgrade:\n-- 1. Diff old and new config:\ndiff /pg15/data/postgresql.conf /pg16/data/postgresql.conf\n\n-- 2. Copy custom settings (carefully):\n# Don't blindly copy - some params change:\n# PG 14: wal_keep_segments → wal_keep_size\n# PG 15: new recovery parameters\n# PG 16: new replication defaults\n\n-- 3. Merge pg_hba.conf:\ndiff /pg15/data/pg_hba.conf /pg16/data/pg_hba.conf\ncp /pg15/data/pg_hba.conf /pg16/data/pg_hba.conf\n\n-- 4. Copy postgresql.auto.conf if using ALTER SYSTEM:\ncp /pg15/data/postgresql.auto.conf /pg16/data/", tags: ['admin', 'pg-upgrade', 'configuration', 'migration'] },
  { id: 'pg-admin-l4-081', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you monitor WAL generation rate and its impact on replication?', options: ['WAL generation rate cannot be monitored', 'Track pg_stat_wal (PG 14+) for wal_bytes and wal_records over time, and compare with replication throughput in pg_stat_replication — a WAL generation rate exceeding replication bandwidth causes increasing lag that may require network upgrades or WAL compression', 'Use pg_stat_database for WAL stats', 'WAL rate is always constant'], correctAnswer: 1, explanation: 'pg_stat_wal (PG 14+) shows cumulative WAL statistics. Sample it periodically to calculate rate: (wal_bytes_now - wal_bytes_prev) / interval = bytes/sec. Compare with replication throughput. High WAL rates from bulk operations can cause temporary lag spikes. wal_compression reduces WAL volume. Monitoring WAL rate helps capacity planning.', codeSnippet: "-- WAL generation stats (PG 14+):\nSELECT wal_records, wal_fpi, wal_bytes,\n  pg_size_pretty(wal_bytes) AS wal_total,\n  wal_buffers_full, wal_write, wal_sync,\n  stats_reset\nFROM pg_stat_wal;\n\n-- Calculate WAL rate (run twice, diff):\nSELECT pg_size_pretty(\n  pg_wal_lsn_diff(\n    pg_current_wal_lsn(),\n    '0/0'::pg_lsn\n  )\n) AS total_wal_generated;\n\n-- Reduce WAL generation:\nALTER SYSTEM SET wal_compression = 'lz4';  -- PG 15+ algo\nALTER SYSTEM SET wal_compression = 'on';   -- PG 11+ pglz\nALTER SYSTEM SET full_page_writes = on;  -- required\n\n-- Monitor WAL file count:\nSELECT count(*) FROM pg_ls_waldir();", tags: ['admin', 'pg-stat-replication', 'wal-rate', 'capacity-planning'] },
  { id: 'pg-admin-l4-082', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Logical Replication', question: 'How do you set up logical replication with SSL/TLS encryption?', options: ['Logical replication does not support SSL', 'Configure SSL on both publisher and subscriber PostgreSQL instances, then use sslmode=verify-full in the subscription CONNECTION string along with sslcert, sslkey, and sslrootcert parameters to encrypt and authenticate the replication connection', 'SSL is automatic for replication', 'Use a VPN instead of SSL'], correctAnswer: 1, explanation: 'Logical replication connections use standard libpq connection parameters. sslmode=verify-full ensures both encryption and server identity verification. Client certificate authentication adds mutual TLS. This protects replication data in transit, which is critical when replicating across networks or cloud regions.', codeSnippet: "-- Publisher: enable SSL\nssl = on\nssl_cert_file = '/etc/ssl/pg/server.crt'\nssl_key_file = '/etc/ssl/pg/server.key'\nssl_ca_file = '/etc/ssl/pg/ca.crt'\n\n-- Subscriber: create subscription with SSL\nCREATE SUBSCRIPTION secure_sub\n  CONNECTION 'host=publisher dbname=mydb\n    user=repl_user\n    sslmode=verify-full\n    sslcert=/etc/ssl/pg/client.crt\n    sslkey=/etc/ssl/pg/client.key\n    sslrootcert=/etc/ssl/pg/ca.crt'\n  PUBLICATION my_pub;\n\n-- Verify SSL is in use:\nSELECT pid, ssl, ssl_version, ssl_cipher\nFROM pg_stat_ssl\nJOIN pg_stat_replication USING (pid);", tags: ['admin', 'logical-replication', 'ssl', 'security'] },
  { id: 'pg-admin-l4-083', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is the archive_library parameter introduced in PostgreSQL 15?', options: ['It specifies which shared library to load', 'archive_library (PG 15+) allows loading a shared library module for WAL archiving instead of forking a shell command for each WAL file — this eliminates the overhead of process creation per file and enables more efficient archiving through direct API calls', 'It controls library search paths', 'It sets the archive compression library'], correctAnswer: 1, explanation: 'Traditional archive_command forks a new process for each WAL file, which has overhead. archive_library loads a shared library that handles archiving in-process via the archive module API. PG 15 ships with basic_archive module as a reference implementation. Third-party modules can implement custom archiving (S3, GCS, etc.) more efficiently.', codeSnippet: "-- Traditional approach (forks process per file):\narchive_command = 'cp %p /archive/%f'\n\n-- PG 15+: Use archive library (in-process):\narchive_library = 'basic_archive'\nbasic_archive.archive_directory = '/archive'\n\n-- Using archive_library:\n-- - No process fork overhead\n-- - Direct file operations\n-- - Can implement custom logic in C\n-- - Faster for high WAL throughput\n\n-- Note: archive_command and archive_library\n-- are mutually exclusive\n-- If archive_library is set, archive_command\n-- is ignored\n\n-- Check current archiving status:\nSELECT * FROM pg_stat_archiver;", tags: ['admin', 'pitr', 'archive-library', 'pg15'] },
  { id: 'pg-admin-l4-084', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_upgrade', question: 'How do you handle pg_upgrade when using tablespaces?', options: ['Tablespaces are dropped during upgrade', 'pg_upgrade preserves tablespace mappings; if new cluster uses different paths, use -T (--old-tablespace-mapping) to remap old tablespace locations to new ones — tablespace directories must exist and be empty in the new cluster before running pg_upgrade', 'Tablespaces must be recreated after upgrade', 'pg_upgrade does not support tablespaces'], correctAnswer: 1, explanation: 'pg_upgrade handles tablespaces by either: (1) Using the same paths (default), (2) Remapping with -T old=new. In link mode, tablespace data is hard-linked from old to new locations. The new cluster tablespace directories must be created (empty) before pg_upgrade. After upgrade, verify tablespace paths and permissions.', codeSnippet: "-- List tablespaces before upgrade:\nSELECT spcname, pg_tablespace_location(oid)\nFROM pg_tablespace;\n\n-- Same paths (default):\npg_upgrade \\\n  --old-datadir=/pg15/data \\\n  --new-datadir=/pg16/data \\\n  --old-bindir=/pg15/bin \\\n  --new-bindir=/pg16/bin\n\n-- Different paths:\nmkdir -p /new/fast_ssd/pg_tblspc\npg_upgrade \\\n  --old-datadir=/pg15/data \\\n  --new-datadir=/pg16/data \\\n  --old-bindir=/pg15/bin \\\n  --new-bindir=/pg16/bin \\\n  -T /old/fast_ssd/pg_tblspc=/new/fast_ssd/pg_tblspc\n\n-- Verify after upgrade:\nSELECT spcname, pg_tablespace_location(oid)\nFROM pg_tablespace;", tags: ['admin', 'pg-upgrade', 'tablespaces', 'path-mapping'] },
  { id: 'pg-admin-l4-085', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Huge Pages', question: 'How do you troubleshoot PostgreSQL failing to start with huge_pages = on?', options: ['Switch to huge_pages = off', 'Check that sufficient huge pages are allocated (grep Huge /proc/meminfo), verify the postgres user has permission to use them (vm.hugetlb_shm_group), ensure no other process consumed them, and calculate the correct number based on shared memory requirements', 'Increase shared_buffers', 'Reinstall PostgreSQL'], correctAnswer: 1, explanation: 'Common causes of startup failure: (1) HugePages_Free = 0 (all consumed by other processes), (2) Not enough total pages allocated, (3) postgres user not in hugetlb_shm_group, (4) shared_buffers increased without increasing nr_hugepages, (5) THP consuming available huge pages. Check PostgreSQL log for specific error message.', codeSnippet: "-- Step 1: Check huge page availability:\ngrep Huge /proc/meminfo\n# HugePages_Total: 0     <- PROBLEM: not configured\n# HugePages_Free:  0     <- PROBLEM: all consumed\n# Hugepagesize:    2048 kB\n\n-- Step 2: Check permissions:\nid postgres  # get GID\ncat /proc/sys/vm/hugetlb_shm_group  # should match\nsudo sysctl -w vm.hugetlb_shm_group=$(id -g postgres)\n\n-- Step 3: Allocate enough pages:\n# shared_buffers = 8GB → 8192MB / 2MB = 4096 + margin\nsudo sysctl -w vm.nr_hugepages=4500\n\n-- Step 4: Check PostgreSQL log:\n# FATAL: could not map anonymous shared memory:\n#   Cannot allocate memory\n# HINT: This error usually means that PostgreSQL's\n#   request for a shared memory segment exceeded\n#   available memory, swap space, or huge pages.", tags: ['admin', 'huge-pages', 'troubleshooting', 'startup-failure'] },
  { id: 'pg-admin-l4-086', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'pg_stat_replication', question: 'How do you use pg_stat_replication to implement read-only query routing?', options: ['pg_stat_replication cannot help with routing', 'Application load balancers can query pg_stat_replication to identify healthy standbys with acceptable lag, then route read queries to those standbys — standbys with state = streaming and replay_lag below threshold are candidates for read traffic', 'Use DNS for routing instead', 'PostgreSQL routes queries automatically'], correctAnswer: 1, explanation: 'Connection poolers (pgBouncer, HAProxy, Odyssey) and application frameworks can use health check queries against pg_stat_replication to determine which standbys are healthy and current. Route reads to standbys with low lag for eventual consistency, or to synchronous standbys for strong consistency reads.', codeSnippet: "-- HAProxy health check endpoint on primary:\n-- Returns healthy standbys for read routing\n\n-- Health check query for standbys:\nSELECT CASE\n  WHEN pg_is_in_recovery()\n    AND pg_last_wal_receive_lsn() = pg_last_wal_replay_lsn()\n  THEN 'OK: standby is current'\n  WHEN pg_is_in_recovery()\n    AND now() - pg_last_xact_replay_timestamp()\n      < interval '5 seconds'\n  THEN 'OK: standby lag acceptable'\n  ELSE 'FAIL: standby too far behind'\nEND AS status;\n\n-- Primary check (for write routing):\nSELECT CASE\n  WHEN NOT pg_is_in_recovery()\n  THEN 'OK: primary'\n  ELSE 'FAIL: not primary'\nEND;\n\n-- Connection string with multiple hosts:\n-- host=primary,standby1,standby2\n-- target_session_attrs=read-write  (primary)\n-- target_session_attrs=prefer-standby  (PG 14+)", tags: ['admin', 'pg-stat-replication', 'read-routing', 'load-balancing'] },
  { id: 'pg-admin-l4-087', language: 'postgresql', level: 'level4', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you implement a delayed standby for protection against logical errors?', options: ['Delayed standbys are not possible', 'Configure recovery_min_apply_delay on a standby to intentionally delay WAL replay by a specified duration — this provides a time window to catch and recover from logical errors (accidental DROP TABLE, bad UPDATE) before they are applied to the delayed standby', 'Use a cron job to pause replication', 'Set wal_sender_timeout to a large value'], correctAnswer: 1, explanation: 'A delayed standby applies WAL with a configurable time lag (e.g., 1 hour). If someone accidentally drops a table, you have up to 1 hour to notice and recover from the delayed standby before the DROP is applied there. The standby still receives WAL in real-time (no data loss), but replays it with a delay.', codeSnippet: "-- On delayed standby: postgresql.conf\nprimary_conninfo = 'host=primary user=repl_user'\nrecovery_min_apply_delay = '1h'  -- 1 hour delay\n\n-- The standby receives WAL in real-time\n-- but delays replay by 1 hour\n\n-- Check delay status:\nSELECT pg_last_wal_receive_lsn() AS received,\n  pg_last_wal_replay_lsn() AS replayed,\n  pg_last_xact_replay_timestamp() AS replay_time,\n  now() - pg_last_xact_replay_timestamp() AS delay;\n\n-- Emergency: skip delay and catch up\n-- (when you need current data from delayed standby)\npg_ctl promote -D /delayed_standby/data\n-- Or: ALTER SYSTEM SET recovery_min_apply_delay = 0;\n-- SELECT pg_reload_conf();  -- catches up quickly\n\n-- Use case: recover dropped table\n-- pg_dump -h delayed_standby -t dropped_table > recover.sql\n-- psql -h primary < recover.sql", tags: ['admin', 'pitr', 'delayed-standby', 'disaster-recovery'] },
];

export default questions;
